const t = (schluessel, werte) => text(TEXTE, schluessel, werte);

// Antwortwoerter versteht der Installer in beiden Sprachen: Eine Pipe mit deutschen Antworten
// laeuft auch in einem englischen Projekt, und umgekehrt.
const JA = new Set(["j", "ja", "y", "yes"]);
const NEIN = new Set(["n", "nein", "no"]);

/**
 * So schreibt der Installer jede Config (Issue #1728, Plan #1710 A2, E1): jede Einstellung unter
 * ihrem englischen Namen, gleich in welcher Sprache das Projekt arbeitet, `sprache` als
 * `language`. Ein Aufzaehlungswert, der in `roh` (der Datei vor dem Schreiben) steht, behaelt
 * seine Schreibweise; ein neuer bekommt den englischen Wert.
 */
function zumSchreiben(config, roh) {
  return mitEnglischenNamen(benenneWieVorlage(config, roh ?? {}, "en", { werte: "wie-vorlage" }));
}

/** Die Config-Datei, wie sie auf der Platte steht, oder `{}`, wenn es sie nicht gibt oder sie kein lesbares Objekt ist. */
function leseRoh(configPfad) {
  try {
    const roh = JSON.parse(readFileSync(configPfad, "utf-8"));
    return roh !== null && typeof roh === "object" && !Array.isArray(roh) ? roh : {};
  } catch {
    return {};
  }
}

/** Die Eintraege der Datei `roh`, die das Schreiben auf ihren englischen Namen umbenennt, je `{ alt, neu }`. */
function umbenannteEinstellungen(roh) {
  const liste = benenneUm(roh, "en", { werte: "wie-vorlage" }).umbenannt.map((u) => ({ alt: u.von, neu: u.nach }));
  if (Object.hasOwn(roh, "sprache") && !Object.hasOwn(roh, "language")) liste.push({ alt: "sprache", neu: "language" });
  return liste;
}

/**
 * Das Update nennt in einer Zeile, wie viele Eintraege der Datei `roh` das Schreiben auf ihren
 * englischen Namen umbenannt hat, `lokal` (die Umbenennungen der persoenlichen Datei) zaehlt
 * dazu (Issue #1729); eine Ersteinrichtung hat nichts umzubenennen.
 */
function meldeUmbenannt(ersteinrichtung, roh, lokal) {
  if (ersteinrichtung) return;
  console.log(t("namenUmgestellt", { anzahl: umbenannteEinstellungen(roh).length + lokal.length }));
}

function streichePfad(wert, [name, ...rest]) {
  if (wert === null || typeof wert !== "object" || Array.isArray(wert)) return;
  if (rest.length === 0) delete wert[name];
  else streichePfad(wert[name], rest);
}

/**
 * Das Update migriert auch die persoenliche Datei `workflow.config.local.json` (Issue #1729, Plan
 * #1710 A3, A11, A12, E2): Schluessel englisch, jeder Wert unveraendert, `provider` und die
 * entfallenen Pfade fort. Die Datei ist nicht versioniert, Git ist fuer sie kein Rueckweg; darum
 * sichert der Schritt sie vor dem Schreiben nach `.vor-update`. Aendert sich nichts, bleibt sie
 * byte-gleich und ohne Sicherung, ebenso eine unlesbare Datei. `provider` wird nicht auf
 * codeHost/issueTracker uebertragen: Die geteilte Datei traegt beide nach dem Update immer, ein
 * uebertragener Wert in der persoenlichen Datei wuerde sie ueberstimmen. Gibt die umbenannten
 * Eintraege zurueck, je `{ alt, neu }`.
 */
function migriereLokaleConfig(targetBase) {
  const lokalPfad = join(targetBase, "workflow.config.local.json");
  if (!existsSync(lokalPfad)) return [];
  const original = readFileSync(lokalPfad, "utf-8");
  let roh;
  try {
    roh = JSON.parse(original);
  } catch {
    return [];
  }
  if (roh === null || typeof roh !== "object" || Array.isArray(roh)) return [];
  const neu = mitEnglischenNamen(roh);
  // Die entfallenen Pfade tragen die deutschen Namen; ihre Eltern heissen in beiden Sprachen gleich.
  for (const pfad of ENTFALLEN) streichePfad(neu, pfad.split("."));
  delete neu.provider;
  if (JSON.stringify(neu) === JSON.stringify(roh)) return [];
  const davor = () => writeFileSync(`${lokalPfad}.vor-update`, original, "utf-8");
  return schreibeKitDatei(lokalPfad, JSON.stringify(neu, null, 2) + "\n", { davor }) ? umbenannteEinstellungen(roh) : [];
}

// Die Config-Felder, die Labelnamen tragen (E7). Ein gesetzter Wert bleibt, wie er ist; die
// Umstellung nennt ihn nur, wenn er ein Kit-Label in der anderen Sprache ist.
const LABEL_FELDER = [
  ["night", "kette", "label"], ["night", "kette", "varianteBLabel"], ["pruefLauf", "label"],
  ["night", "stand", "labels", "laeuft"], ["night", "stand", "labels", "abgebrochen"], ["night", "stand", "labels", "wartet"],
];

function offeneLabels(config, ziel) {
  const offen = [];
  for (const pfad of LABEL_FELDER) {
    const wert = pfad.reduce((knoten, name) => knoten?.[name], config);
    const sache = erkenneLabel(wert);
    if (sache && LABELS[sache][ziel] !== wert) offen.push(t("labelOffen", { pfad: pfad.join("."), wert, ziel, name: LABELS[sache][ziel] }));
  }
  return offen;
}

/**
 * Der Board-Teil des Berichts (E12): Karten mit Praefix der anderen Sprache und Kit-Labels der
 * Zielsprache, die auf keiner Karte stehen. Gelesen ueber `issue list` der installierten
 * board.mjs; scheitert der Aufruf, steht das im Bericht, und die Umstellung bleibt.
 */
function boardBestand(ziel) {
  const board = resolve(".claude", "kit", "board.mjs");
  const res = cliSpawn(process.execPath, [board, "issue", "list"], "INSTALL_BOARD_FAKE", { encoding: "utf-8", timeout: 120000 });
  let karten = null;
  try { karten = res.status === 0 ? JSON.parse(res.stdout) : null; } catch { /* keine lesbare Antwort */ }
  if (!Array.isArray(karten)) {
    const grund = (res.error?.message ?? res.stderr ?? "").trim().split("\n").pop() || `Exit ${res.status}`;
    return [t("boardNicht", { grund })];
  }
  const zeilen = [];
  for (const karte of karten) {
    const paar = PRAEFIXE[erkennePraefix(karte.title)];
    if (!paar || paar.de === paar.en) continue;
    if (karte.title.trimStart().toLowerCase().startsWith(paar[ziel].toLowerCase())) continue;
    zeilen.push(t("karteAndereSprache", { id: karte.id, titel: karte.title }));
  }
  const gesehen = new Set(karten.flatMap((k) => k.labels ?? []));
  // Ohne Runner legt die Einrichtung seine Labels nicht an (#1814 PO-Antwort 3, Plan #1853 E7);
  // in Community wie in Pro, denn der Runner ist Community (Issue #2019, Plan #2008 A6).
  const fehlend = Object.values(LABELS)
    .filter((l) => l.de !== l.en && !gesehen.has(l[ziel]) && (MIT_RUNNER || !l.nurRunner))
    .map((l) => l[ziel]);
  if (fehlend.length > 0) zeilen.push(t("labelsFehlend", { ziel, labels: fehlend.join(", ") }));
  return zeilen;
}

// Ein Schluessel steht unter seinem Elternpfad, ein Wert unter seinem eigenen Pfad.
function umbenennungsZeile(u) {
  if (u.art === "wert") return `${u.pfad}: ${u.von} → ${u.nach}`;
  const trenner = u.pfad.lastIndexOf(".");
  const zeile = `${u.von} → ${u.nach}`;
  return trenner < 0 ? zeile : `${u.pfad.slice(0, trenner)}: ${zeile}`;
}

/** Die Zielsprache aus `--language <de|en>` oder `--language=<..>`; sonst `null`. */
function umstellSprache(argv) {
  for (let i = 0; i < argv.length; i++) {
    const treffer = /^--(language)(?:=(.*))?$/.exec(argv[i]);
    if (!treffer) continue;
    const wert = (treffer[2] ?? argv[i + 1] ?? "").trim().toLowerCase();
    if (!SPRACHEN.includes(wert)) throw new Error(t("spracheFalsch", { option: treffer[1], wert }));
    return wert;
  }
  return null;
}

/**
 * `node install.mjs --language en|de` (E12): stellt ein bestehendes Projekt um. Sichert die
 * Config nach `workflow.config.json.vor-umstellung`, stellt die Aufzaehlungswerte in Config und
 * Override-Datei um, setzt das Sprachfeld und listet, was umbenannt wurde und was offen bleibt.
 * Schluessel stellt sie nicht um: Sie sind in jeder Sprache englisch (Issue #1728, Plan #1710 A4),
 * und eine geschriebene Datei traegt sie so. Labelwerte aendert sie nicht (E7). Regeltexte, Pruefer und Pruefrollen
 * legt sie in der neuen Sprache ab; was davon deutsch bleibt, steht unter "Offen" (Issue #1464).
 * Skills tauscht sie nicht, die gibt es seit Issue #1566 nur in einer Fassung.
 */
function umstellModus(ziel) {
  const configPfad = resolve(".claude", "workflow.config.json");
  if (!existsSync(configPfad)) {
    throw new Error(t("umstellungOhneConfig"));
  }
  const original = readFileSync(configPfad, "utf-8");
  const { config: umbenannt, umbenannt: alle } = benenneUm(JSON.parse(original), ziel);
  const liste = alle.filter((u) => u.art === "wert");
  const { language: _l, sprache: _s, ...rest } = mitEnglischenNamen(umbenannt);
  const config = { [SPRACHFELD]: ziel, ...rest };

  writeFileSync(`${configPfad}.vor-umstellung`, original, "utf-8");
  schreibeKitDatei(configPfad, JSON.stringify(config, null, 2) + "\n");
  console.log(t("sicherung", { pfad: `${configPfad}.vor-umstellung` }));
  console.log(t("spracheGesetzt", { feld: SPRACHFELD, ziel }));
  const rueckfall = schreibeSprachfassungen(resolve(".claude"), ziel);

  const zeilen = liste.map(umbenennungsZeile);
  const lokalPfad = resolve(".claude", "workflow.config.local.json");
  if (existsSync(lokalPfad)) {
    const lokal = benenneUm(JSON.parse(readFileSync(lokalPfad, "utf-8")), ziel);
    const werte = lokal.umbenannt.filter((u) => u.art === "wert");
    if (werte.length > 0) schreibeKitDatei(lokalPfad, JSON.stringify(mitEnglischenNamen(lokal.config), null, 2) + "\n");
    zeilen.push(...werte.map((u) => `workflow.config.local.json: ${umbenennungsZeile(u)}`));
  }
  console.log(t("umbenannt", { anzahl: zeilen.length }));
  for (const z of zeilen) console.log(`  ${z}`);

  const offen = [...offeneLabels(normalisiereConfig(config).config, ziel), ...boardBestand(ziel), ...rueckfall];
  console.log(t("offen", { anzahl: offen.length }));
  for (const z of offen) console.log(`  ${z}`);
  console.log(t("zurueck", { ziel: ziel === "en" ? "de" : "en" }));
}

// Fragen 7 und 8 (das Reviewer-Paar) als eigene Schleife, wie promptScope: Sie werden
// gemeinsam wiederholt, weil die Regel "genau eines von beiden" erst mit beiden Antworten
// pruefbar ist (Issue #433).
//
// Der leere Default fuer reviewModel gilt in zwei Faellen. Traegt die Bestandsconfig
// einen Kommando-Reviewer ALLEIN, ist das der ausloesende Fall aus Issue #433: Er soll
// sich per Enter bestaetigen lassen. Traegt sie BEIDE Felder nicht-leer, wird der
// Widerspruch hier aufgeloest, statt ihn nur abzuweisen — vorgeschlagen wurden sonst
// beide Bestandswerte und abgewiesen genau diese Kombination, und wer bestaetigt, was
// ihm vorgeschlagen wird, kam nicht heraus (Issue #480). Weil das Kommando ohne eigene
// Frage nicht rekonstruierbar waere, das Modell aber jederzeit neu eingetippt ist,
// behaelt reviewCommand seinen Bestandswert; still umgeschrieben wird nichts, der
// Hinweis unten benennt den Eingriff vor der ersten Frage.
async function promptReviewerPaar(rl, D, existingConfig) {
  const beideGesetzt = Boolean(existingConfig.reviewModel && existingConfig.reviewCommand);
  const reviewModelDefault =
    beideGesetzt || (existingConfig.reviewCommand && !existingConfig.reviewModel)
      ? ""
      : D.reviewModel;

  if (beideGesetzt) {
    console.log(`\n${t("reviewerWiderspruch")}`);
    console.log(t("reviewCommandBleibt", { kommando: existingConfig.reviewCommand }));
    console.log(t("reviewerUmgekehrt", { leer: LEER_EINGABE }));
  }

  while (true) {
    const reviewModel = await askWithDefault(  // eslint-disable-line no-await-in-loop -- NOSONAR S9382: fragt an der Konsole erneut, bis die Eingabe gueltig ist
      rl,
      t("frageReviewModel", { leer: LEER_EINGABE }),
      reviewModelDefault,
      "reviewModel",
      true
    );
    const reviewCommand = await askWithDefault(  // eslint-disable-line no-await-in-loop -- NOSONAR S9382: fragt an der Konsole erneut, bis die Eingabe gueltig ist
      rl,
      t("frageReviewCommand", { leer: LEER_EINGABE }),
      D.reviewCommand ?? "",
      "reviewCommand",
      true
    );
    const fehler = validateFelder({ reviewModel, reviewCommand });
    if (!fehler) return { reviewModel, reviewCommand };
    console.error(t("fehlerZeile", { fehler }));
    // Interaktiv werden genau diese beiden Fragen erneut gestellt; die uebrigen
    // Antworten bleiben stehen. Im Pipe-Modus antwortet niemand nach — dort bricht es ab.
    if (_pipedLines !== null) throw new Error(`Validation failed in non-interactive mode: ${fehler}`);
  }
}

/**
 * Die Strenge des Projekts (Issue #2114, Plan #2102 A15; #2100 Kriterium 1): nur projektlokal,
 * denn die Strenge gilt je Projekt. Vorgeschlagen ist die bestehende Strenge, sonst `normal`, in
 * der Sprache des Projekts; angenommen werden die Werte beider Sprachen. Liefert `{ strenge }`
 * mit dem internen Wert, global `{}` — dann bleibt die Config, wie sie ist.
 */
async function frageStrenge(rl, scope, vorgabe) {
  if (scope !== "projekt") return {};
  const intern = (wert) => normalisiereConfig({ strenge: wert }).config.strenge;
  const angezeigt = prozessSprache() === "en" ? benenneUm({ strenge: intern(vorgabe) }, "en").config.strictness : intern(vorgabe);
  const antwort = await askWithDefault(rl, t("frageStrenge"), angezeigt, "strenge");
  return { strenge: intern(antwort) };
}

// --- Die Bereiche des Projekts (Issue #1009, Plan #1001 E10) -----------------
//
// Die letzte projektlokale Frage: erst die Bereiche (checkAreas), dann je vorhandener
// Pruefung ihre Zuordnung (areas). Eine falsche Eingabe wird hier auch im Pipe-Modus
// erneut gefragt statt abgebrochen — die Schleife endet trotzdem, weil eine
// erschoepfte Pipe mit "" antwortet, und "" heisst an jeder Stelle "fertig".

/** "name: muster, muster" → { name, muster } oder null bei falscher Form. */
function liesBereich(eingabe) {
  const doppelpunkt = eingabe.indexOf(":");
  const name = eingabe.slice(0, Math.max(doppelpunkt, 0)).trim();
  const muster = eingabe.slice(doppelpunkt + 1).split(",").map((m) => m.trim()).filter(Boolean);
  if (doppelpunkt < 0 || !name || muster.length === 0) return null;
  return { name, muster };
}

/**
 * Fragt die Bereiche ab. `null` heisst: gleich die erste Eingabe war leer, es bleibt,
 * wie es ist. Vorhandene Bereiche bleiben erhalten; ein neu genannter gleichen Namens
 * ersetzt seine Muster.
 */
async function frageBereichsliste(rl, vorhanden) {
  const namen = Object.keys(vorhanden);
  if (namen.length > 0) {
    console.log(t("bereicheVorhanden"));
    for (const name of namen) console.log(`    ${name}: ${vorhanden[name].join(", ")}`);
  } else {
    console.log(t("bereicheErklaerung"));
  }
  const bereiche = { ...vorhanden };
  let neu = 0;
  while (true) {
    const vorgabe = namen.length > 0 && neu === 0 ? t("bereichBeibehalten") : "";
    const eingabe = (await ask(rl, `${t("bereichFrage")}${vorgabe}: `)).trim();  // eslint-disable-line no-await-in-loop -- NOSONAR S9382: ein Bereich nach dem anderen an der Konsole
    if (eingabe === "") return neu === 0 ? null : bereiche;
    const bereich = liesBereich(eingabe);
    if (!bereich) {
      console.error(t("fehlerZeile", { fehler: t("bereichFalsch") }));
      continue;
    }
    bereiche[bereich.name] = bereich.muster;
    neu++;
  }
}

/** Fragt die Bereiche einer Pruefung; leer laesst den Eintrag, wie er ist. */
async function frageZuordnung(rl, check, bereiche) {
  const cmd = typeof check === "string" ? check : check.cmd;
  const vorhanden = typeof check === "object" && check.areas ? check.areas.join(", ") : "";
  const frage = vorhanden
    ? t("zuordnungMit", { vorhanden })
    : t("zuordnungOhne");
  console.log(t("zuordnungPruefung", { kommando: cmd }));
  while (true) {
    const eingabe = (await ask(rl, frage)).trim();  // eslint-disable-line no-await-in-loop -- NOSONAR S9382: fragt an der Konsole erneut, bis die Eingabe gueltig ist
    if (eingabe === "") return check;
    const namen = eingabe.split(",").map((n) => n.trim()).filter(Boolean);
    const unbekannt = namen.filter((n) => !Object.hasOwn(bereiche, n));
    if (unbekannt.length === 0) {
      // areas und always schliessen sich aus (Schema); stufe und die uebrigen Achsen bleiben.
      const { always: _always, ...rest } = typeof check === "string" ? { cmd } : check;
      return { ...rest, areas: namen };
    }
    const fehler = t("bereichUnbekannt", { unbekannt: unbekannt.join("', '"), definiert: Object.keys(bereiche).join(", ") });
    console.error(t("fehlerZeile", { fehler }));
  }
}

// --- Der Bereichsvorschlag (Issue #1721, Plan #1713 A13, E3, E4) ------------
//
// Beim ersten Einrichten gibt es `.claude/kit/` noch nicht: Die eingebetteten Dateien fuer
// `areas suggest` gehen in ein Wegwerf-Verzeichnis, das Kommando laeuft dort als Kindprozess
// ohne Config. Das Update faehrt dagegen die eben geschriebene Kopie unter `.claude/kit/` und
// nennt nur den Befehl — es fragt nichts und aendert die Config nicht.

// Die Messung liest jede Datei des Arbeitsstands; ein grosses Projekt darf dauern.
const VORSCHLAG_TIMEOUT_MS = 120_000;

/** Der Vorschlag aus dem Lauf von `areas suggest --json`, oder null ohne abgeleiteten Bereich. */
function vorschlagAusLauf(res) {
  if (res.status !== 0) return null;
  const vorschlag = JSON.parse(res.stdout);
  return vorschlag.bereiche?.length > 0 ? vorschlag : null;
}

/** Faehrt `areas suggest` aus einer Wegwerf-Kopie fuer das Projekt in `projektDir`; jeder Fehler heisst „kein Vorschlag". */
function bereichsvorschlagHolen(projektDir) {
  let kopie = null;
  try {
    kopie = mkdtempSync(join(tmpdir(), "kit-bereichsvorschlag-"));
    writeFileSync(join(kopie, "checks.mjs"), Buffer.from(CHECKS_MJS_B64, "base64").toString("utf-8"), "utf-8");
    for (const [teil, blob] of [["checks", KIT_CHECKS_B64], ["texte", KIT_TEXTE_B64]]) {
      mkdirSync(join(kopie, teil), { recursive: true });
      for (const [datei, inhalt] of Object.entries(blobJson(blob))) writeFileSync(join(kopie, teil, datei), inhalt, "utf-8");
    }
    // Arbeitsverzeichnis statt `--in`: `areas suggest` misst das Verzeichnis, in dem es laeuft.
    return vorschlagAusLauf(spawnSync(process.execPath, [join(kopie, "checks.mjs"), "areas", "suggest", "--json"], {
      cwd: projektDir, encoding: "utf-8", timeout: VORSCHLAG_TIMEOUT_MS,
    }));
  } catch {
    return null;
  } finally {
    if (kopie) rmSync(kopie, { recursive: true, force: true });
  }
}

/**
 * Bietet den Vorschlag an: `j` uebernimmt ihn, `a` faehrt die Bereichsfrage mit ihm als
 * vorhandenen Bereichen, leer ueberspringt. Liefert die Bereiche oder null.
 */
async function frageVorschlag(rl, vorschlag) {
  const vorgeschlagen = vorschlag.ausschnitt.checkAreas;
  console.log(t("vorschlagKopf"));
  for (const [name, muster] of Object.entries(vorgeschlagen)) console.log(`    ${name}: ${muster.join(", ")}`);
  while (true) {
    const antwort = (await ask(rl, t("vorschlagFrage"))).trim().toLowerCase();  // eslint-disable-line no-await-in-loop -- NOSONAR S9382: fragt an der Konsole erneut, bis die Eingabe gueltig ist
    if (antwort === "") return null;
    if (JA.has(antwort)) {
      console.log(t("vorschlagUebernommen"));
      return vorgeschlagen;
    }
    if (antwort === "a") return (await frageBereichsliste(rl, vorgeschlagen)) ?? vorgeschlagen;  // eslint-disable-line no-await-in-loop -- NOSONAR S9382: die Liste folgt dieser Antwort an der Konsole
    console.error(t("fehlerZeile", { fehler: t("vorschlagFalsch") }));
  }
}

/** Nach dem Update eines Projekts ohne Bereiche: eine Zeile mit dem Befehl, wenn ein Vorschlag bereitliegt. */
function meldeBereichsvorschlag(kitDir, scope, ersteinrichtung, config) {
  if (scope !== "projekt" || ersteinrichtung || Object.keys(config.checkAreas ?? {}).length > 0) return;
  try {
    const res = spawnSync(process.execPath, [join(kitDir, "checks.mjs"), "areas", "suggest", "--json"], {
      encoding: "utf-8", timeout: VORSCHLAG_TIMEOUT_MS,
    });
    if (vorschlagAusLauf(res)) console.log(`\n${t("vorschlagBereit")}`);
  } catch { /* kein Vorschlag, keine Zeile */ }
}

/**
 * Die Bereichsfrage — nur projektlokal. Liefert die Felder, die in die Config gehen,
 * oder null, wenn nichts zu aendern ist. Beim ersten Einrichten bietet sie zuerst den
 * gemessenen Vorschlag an, wenn es einen gibt (Issue #1721).
 */
async function frageBereiche(rl, scope, existingConfig, ersteinrichtung) {
  if (scope !== "projekt") return null;
  const vorhanden = existingConfig.checkAreas ?? {};
  const vorschlag = ersteinrichtung ? bereichsvorschlagHolen(process.cwd()) : null;
  const checkAreas = vorschlag
    ? await frageVorschlag(rl, vorschlag)
    : await frageBereichsliste(rl, vorhanden);
  if (!checkAreas) {
    console.log(Object.keys(vorhanden).length > 0
      ? t("bereicheBehalten")
      : t("ohneBereiche"));
    return null;
  }
  const checks = existingConfig.buildChecks ?? [];
  if (checks.length === 0) {
    console.log(t("bereicheWirkenErst"));
    return { checkAreas };
  }
  const buildChecks = [];
  for (const check of checks) buildChecks.push(await frageZuordnung(rl, check, checkAreas));  // eslint-disable-line no-await-in-loop -- NOSONAR S9382: eine Frage nach der anderen an der Konsole
  return { checkAreas, buildChecks };
}

// --- Die Vorgaben des Projekttyps (Issue #2115, Plan #2102, Quelle #2100 Kriterium 11) ---
//
// Nach der Bereichsfrage: Der Projekttyp bestimmt, wie schnell die Pruefungen laufen, nie
// welche. Die Erkennung und die Vorgaben stehen in checks/projekttyp.mjs; der Installer laedt
// das Modul aus seinem Blob, weil es beim ersten Einrichten noch kein .claude/kit/ gibt. Gefragt
// wird nur, wenn etwas zu schreiben waere; geschrieben wird nur nach Ja.

const PROJEKTTYP_NAMEN = { maven: "Maven", gradle: "Gradle", npm: "npm", pnpm: "pnpm" };

async function projekttypModul() {
  const quelle = blobJson(KIT_CHECKS_B64)["projekttyp.mjs"];
  return quelle ? import(`data:text/javascript;base64,${Buffer.from(quelle, "utf-8").toString("base64")}`) : null;
}

/**
 * Bietet die Vorgaben des Projekttyps an. Liefert null ohne Ja, sonst die Vorgaben samt
 * Modul; geschrieben wird erst mit der Config (`projekttypAnwenden`).
 */
async function frageProjekttyp(rl, scope, buildChecks) {
  if (scope !== "projekt") return null;
  const modul = await projekttypModul();
  if (!modul) return null;
  const vorgaben = modul.projekttypVorgaben(process.cwd(), buildChecks ?? []);
  if (!vorgaben.typ || !modul.vorgabenOffen(vorgaben)) return null;
  console.log(t("projekttypKopf", { typ: PROJEKTTYP_NAMEN[vorgaben.typ] }));
  for (const { pfad, zeilen } of vorgaben.dateien) console.log(t("projekttypDatei", { pfad, zeilen: zeilen.join(", ") }));
  for (const kommando of vorgaben.zurueckgestellt) console.log(t("projekttypZurueck", { kommando }));
  for (const zeile of vorgaben.hinweise) console.log(t("projekttypHinweis", { zeile }));
  const antwort = (await ask(rl, t("projekttypFrage"))).trim().toLowerCase();
  if (!JA.has(antwort)) {
    console.log(t("projekttypNein"));
    return null;
  }
  return { modul, vorgaben };
}

/** Schreibt die Dateien der angenommenen Vorgaben ins Projekt. */
function projekttypAnwenden(angenommen) {
  if (!angenommen) return;
  for (const pfad of angenommen.modul.vorgabenSchreiben(process.cwd(), angenommen.vorgaben)) {
    console.log(t("projekttypGeschrieben", { pfad }));
  }
}

// --- Das Commit-Gate einhaengen (Issue #473, Plan #467 A2/A11) --------------
//
// Der Hook wandert mit dem Clone, die AKTIVIERUNG nicht: `core.hooksPath` ist lokale
// git-Config. Ein frischer Clone hat die Dateien und kein wirksames Gate, bis jemand
// den Installer laufen laesst — das steht so in der Doku, statt eine Zusicherung zu
// behaupten, die git nicht hergibt.

/** Die Kennungszeile, an der ein von uns geschriebener Hook `<name>` erkennbar ist. */
const hookKennung = (name) => `# claude-workflow-kit ${name}`;
// SYNC: SKRIPT_KENNUNG in kit/board/fassung.mjs (Issue #1842).
const SKRIPT_KENNUNG = "# claude-workflow-kit script";

function gitAntwort(...args) {
  const res = cliSpawn("git", args, "INSTALL_GIT_FAKE", { encoding: "utf-8" });
  // ENOENT: git fehlt im PATH. Kein Repo: Exit ungleich 0. Beides ist kein Abbruch —
  // die Installer-Fixtures sind keine Git-Repos, und ausserhalb eines Repos soll der
  // Installer benutzbar bleiben.
  if (res.error || res.status !== 0) return null;
  return (res.stdout || "").trim();
}

/** Ist das Arbeitsverzeichnis ein Git-Repo mit erreichbarem git? */
function imGitRepo() {
  return gitAntwort("rev-parse", "--git-dir") !== null;
}

/**
 * Liegt im Hooks-Verzeichnis eine AKTIVE Datei?
 *
 * `git init` legt `*.sample`-Dateien an; ohne diesen Ausschluss gaelte jedes frische
 * Repo als belegt. `git rev-parse --git-path hooks` statt `.git/hooks` deckt zugleich
 * Worktrees und Submodule ab, wo `.git` eine Datei ist.
 */
function aktiverHookVorhanden() {
  const hooks = gitAntwort("rev-parse", "--git-path", "hooks");
  if (!hooks || !existsSync(hooks)) return false;
  try {
    return readdirSync(hooks).some((n) => !n.endsWith(".sample")
      && statSync(join(hooks, n)).isFile());
  } catch {
    return false;
  }
}

/**
 * Loest Symlinks so weit auf, wie der Pfad existiert.
 *
 * Reines `realpathSync` genuegt nicht: Die Lage wird bestimmt, BEVOR `.githooks`
 * geschrieben ist — bei einer Erstinstallation gibt es das Verzeichnis noch nicht.
 * Dann wird der Elternpfad aufgeloest und der letzte Name angehaengt. Ohne diese
 * Aufloesung auf beiden Seiten verglichen man Schreibweisen statt Verzeichnisse:
 * Auf macOS zeigt schon `/tmp` auf `/private/tmp`.
 *
 * `realpathSync.native`: die Aufloesung des Betriebssystems selbst, damit git und
 * die Umgebung dieselbe Schreibweise desselben Verzeichnisses liefern (Issue #873).
 */
function aufgeloest(pfad) {
  try { return realpathSync.native(pfad); } catch { /* existiert (noch) nicht */ }
  try { return join(realpathSync.native(dirname(pfad)), basename(pfad)); } catch { return pfad; }
}

/**
 * Meinen `a` und `b` dasselbe Verzeichnis? Verglichen werden die normalisierten Pfade,
 * nicht der Wortlaut (Issue #873); die Gross-/Kleinschreibung gehoert zum Namen.
 */
export function pfadeGleich(a, b) {
  return resolve(a) === resolve(b);
}

/**
 * Zeigt `wert` auf das `.githooks` DIESES Repos — gleich, wie er geschrieben ist?
 *
 * Absolut, mit `./` davor oder ueber einen Symlink: Es bleibt das eigene Gate, und
 * der Installer darf es nicht fuer einen fremden Hook-Manager halten. Verglichen
 * werden die aufgeloesten Verzeichnisse, nicht der Wortlaut; ein `.githooks` an
 * einem anderen Ort faellt dabei heraus.
 */
function zeigtAufEigenesGithooks(wert) {
  const wurzel = gitAntwort("rev-parse", "--show-toplevel");
  if (!wurzel) return false;
  return pfadeGleich(aufgeloest(resolve(wurzel, wert)), aufgeloest(join(wurzel, ".githooks")));
}

/**
 * Was mit `core.hooksPath` geschehen soll — entschieden VOR der Frage.
 *
 * Gelesen wird der EFFEKTIVE Wert (ohne `--local`): Ein global gesetzter hooksPath
 * wuerde durch einen lokalen Eintrag fuer dieses Repo ausgehebelt, und genau das ist
 * der A11-Fall.
 *
 * SYNC: Die Erkennung eines eingehaengten Gates in kit/board/doctor.mjs (gateEingehaengt) liest
 * dieselben Orte, `core.hooksPath` und sonst `git rev-parse --git-path hooks`; install.mjs ist
 * eigenstaendig und wird dort nicht importiert (Plan #1767 E13).
 */
function hooksPathLage(scope) {
  if (scope !== "projekt") return { art: "entfaellt", grund: t("grundGlobal") };
  if (!imGitRepo()) return { art: "entfaellt", grund: t("grundKeinGit") };
  const wert = gitAntwort("config", "--get", "core.hooksPath");
  if (wert === ".githooks") return { art: "schon gesetzt" };
  if (wert && zeigtAufEigenesGithooks(wert)) return { art: "schon gesetzt" };
  if (wert) return { art: "belegt", wert };
  if (aktiverHookVorhanden()) return { art: "belegt", wert: t("aktiveHookDatei") };
  return { art: "frei" };
}

async function promptHooks(rl) {
  console.log(t("hooksErklaerung"));
  while (true) {
    const raw = await ask(rl, t("hooksFrage"));  // eslint-disable-line no-await-in-loop -- NOSONAR S9382: fragt an der Konsole erneut, bis die Eingabe gueltig ist
    const antwort = raw.trim().toLowerCase();
    if (JA.has(antwort)) return true;
    if (antwort === "" || NEIN.has(antwort)) return false;
    const fehler = t("jaNeinFalsch");
    console.error(t("fehlerZeile", { fehler }));
    if (_pipedLines !== null) throw new Error(`Validation failed in non-interactive mode: ${fehler}`);
  }
}

/**
 * Fragt nur, wo die Frage etwas bewirkt — und verbraucht sonst KEINE Antwortzeile.
 * Im Pipe-Modus ist das der Unterschied zwischen gruen und rot: Jede ungefragte Frage
 * verschoebe alle folgenden Antworten.
 */
async function frageHooksPath(rl, scope) {
  const lage = hooksPathLage(scope);
  if (lage.art === "frei") return { setzen: await promptHooks(rl), lage };
  return { setzen: false, lage };
}

/**
 * Haelt die Antwort auf Frage 10 als `commitGate` in der Team-Config fest (Plan #1767 E12).
 *
 * Nur wo die Frage gestellt wurde: Bei `belegt`, `entfaellt` und `schon gesetzt` bleibt das
 * Feld, wie es war. Ein Nein ist ein Verzicht und steht als `false` da; ein Ja nimmt einen
 * frueheren Verzicht zurueck, denn die Vorgabe `true` braucht keinen Eintrag.
 */
function haltVerzichtFest(config, hooks) {
  if (hooks.lage.art !== "frei") return;
  if (hooks.setzen) delete config.commitGate;
  else config.commitGate = false;
}

/**
 * Schreibt Hook und Gate nach `.githooks/` und haengt sie ein, wenn der Mensch
 * zugestimmt hat.
 *
 * Eigene Funktion und nicht in main(): Die vier Lagen von `core.hooksPath` plus der
 * Fremdhook-Fall traegen main() ueber die Komplexitaetsschwelle, die dieses Repo
 * seit Issue #401 haelt.
 *
 * Nach `.githooks/` und NICHT nach `.claude/kit/`: Der von ensureProjectGitignore
 * geschriebene Block schliesst `.claude/*` aus, und ein Clone haette den Hook dann
 * ohne das Programm, das er aufruft — er wiese jeden Commit ab.
 */
function schreibeCommitGate(scope, hooks) {
  // Die Bedingung steht hier und nicht in main(): Dort traegt sie einen Zweig mehr,
  // und main() liegt genau auf der Komplexitaetsschwelle.
  if (scope !== "projekt") return;
  const hooksDir = resolve(".githooks");
  const gateTarget = join(hooksDir, "gate.mjs");
  if (schreibeKitDatei(gateTarget, Buffer.from(GATE_MJS_B64, "base64").toString("utf-8"))) console.log(t("geschrieben", { datei: "gate.mjs", pfad: gateTarget }));

  // post-commit und post-merge starten die Pruefung je Karte (Issue #2156, Plan #2145 E1); sie
  // wirken wie pre-commit erst mit eingehaengtem Gate.
  schreibeHookDatei(hooksDir, "pre-commit", PRE_COMMIT_B64);
  // commit-msg prueft einen Commit, der die Strenge senkt (Issue #2109, Plan #2102 A11).
  schreibeHookDatei(hooksDir, "commit-msg", COMMIT_MSG_B64);
  schreibeHookDatei(hooksDir, "post-commit", POST_COMMIT_B64);
  schreibeHookDatei(hooksDir, "post-merge", POST_MERGE_B64);
  // Das Update laesst core.hooksPath, wie es ist (Issue #1804): kein `hooks`, keine Meldung.
  if (hooks) meldeHooksPath(hooks);
}

/**
 * Ein fremder Hook wird nicht ueberschrieben: `.githooks/` ist eine verbreitete
 * Konvention, und ein Projekt kann dort laengst einen eigenen fahren. Erkennbar ist
 * unserer an der Kennungszeile — ein Dateivergleich schluege bei jeder Version fehl.
 */
function schreibeHookDatei(hooksDir, name, b64) {
  const hookTarget = join(hooksDir, name);
  if (existsSync(hookTarget) && !readFileSync(hookTarget, "utf-8").includes(hookKennung(name))) {
    console.log(t("fremderHook", { pfad: hookTarget }));
    console.log(t("fremderHookHilfe", { hook: name }));
    return;
  }
  if (!schreibeKitDatei(hookTarget, Buffer.from(b64, "base64").toString("utf-8"))) return;
  try {
    chmodSync(hookTarget, 0o755);
  } catch {
    // Ein Dateisystem ohne x-Bit ist kein Grund abzubrechen; der Hook liegt trotzdem da.
  }
  console.log(t("geschrieben", { datei: name, pfad: hookTarget }));
}

/**
 * Die Skripte im Projektordner (Issue #1794): runner.sh, chain.sh, check.sh, doctor.sh,
 * checkrun.sh, update.sh (Issue #1850) und update-all.sh (Issue #1851) nehmen dem Menschen im Terminal die langen
 * `node .claude/kit/…`-Aufrufe ab.
 * Ins Wurzelverzeichnis und nicht nach `.claude/`, weil `./runner.sh` der kuerzeste Weg ist.
 * Eine gleichnamige fremde Datei bleibt stehen wie beim Hook: `check.sh` und `doctor.sh` sind
 * verbreitete Namen. Unsere erkennt die Kennungszeile.
 * Das Kit-Repo bekommt keine (Issue #1854, wie `trageProjektEin`). Liefert die Namen der Skripte,
 * die unsere sind — geschrieben oder mit Kennungszeile vorhanden —, fuer die .gitignore.
 */
function schreibeSkripte(scope) {
  if (scope !== "projekt" || istKitRepo(resolve("."))) return [];
  const geschrieben = [];
  const unsere = [];
  for (const [datei, inhalt] of Object.entries(blobJson(KIT_BIN_B64))) {
    // Ein leeres Skript schreibt der Installer nicht (Issue #1861); ohne Pro fehlen runner.sh,
    // chain.sh und check.sh schon im Blob.
    if (inhalt === "") continue;
    const ziel = resolve(datei);
    if (existsSync(ziel) && !readFileSync(ziel, "utf-8").includes(SKRIPT_KENNUNG)) {
      const aufruf = inhalt.match(/^exec (.*) "\$@"$/m)?.[1] ?? "";
      console.log(t("fremdesSkript", { pfad: ziel, aufruf }));
      continue;
    }
    // Auch eine stehengebliebene Datei mit Kennungszeile ist unsere.
    unsere.push(datei);
    if (!schreibeKitDatei(ziel, inhalt)) continue;
    try {
      chmodSync(ziel, 0o755);
    } catch {
      // Wie beim Hook: Ein Dateisystem ohne x-Bit ist kein Grund abzubrechen.
    }
    geschrieben.push(datei);
  }
  if (geschrieben.length > 0) console.log(t("skripteGeschrieben", { namen: geschrieben.join(", ") }));
  return unsere;
}

/**
 * Traegt die Skripte im Projektordner wurzelverankert in die .gitignore ein (Issue #1854): Der
 * Installer erzeugt sie bei jedem Lauf neu wie die Kit-Kopie unter `.claude/`. Unabhaengig vom
 * `.claude`-Block, weil `ensureProjectGitignore` bei vorhandenem Block sofort zurueckkehrt —
 * ein eingerichtetes Projekt bekaeme die Zeilen sonst nie. Nur fehlende Zeilen; `runner.sh`
 * ohne Schraegstrich zaehlt als vorhanden.
 */
function ensureSkripteGitignore(namen) {
  if (namen.length === 0) return;
  const gitignorePath = resolve(".gitignore");
  const content = existsSync(gitignorePath) ? readFileSync(gitignorePath, "utf-8") : "";
  const trimmed = new Set(content.split(/\r?\n/).map((l) => l.trim()));
  const fehlen = namen.filter((n) => !trimmed.has(`/${n}`) && !trimmed.has(n));
  if (fehlen.length === 0) return;
  const kopf = t("gitignoreSkripteKopf");
  const block = [...(trimmed.has(kopf) ? [] : [kopf]), ...fehlen.map((n) => `/${n}`)].join("\n") + "\n";
  const next = content.endsWith("\n") || content === "" ? content + block : content + "\n" + block;
  if (schreibeKitDatei(gitignorePath, next)) console.log(t("gitignoreSkripte", { namen: fehlen.join(", ") }));
}

/** Setzt `core.hooksPath` oder sagt, warum nicht. */
function meldeHooksPath(hooks) {
  if (hooks.setzen) {
    const res = cliSpawn("git", ["config", "core.hooksPath", ".githooks"], "INSTALL_GIT_FAKE", { encoding: "utf-8" });
    if (res.error || res.status !== 0) {
      const fehler = t("hooksPathFehler", { grund: (res.stderr || res.error?.message || "").trim() });
      console.error(t("fehlerZeile", { fehler }));
      process.exitCode = 1;
      return;
    }
    console.log(t("hooksPathGesetzt"));
    return;
  }
  if (hooks.lage.art === "belegt") {
    console.log(t("hooksPathBelegt", { wert: hooks.lage.wert }));
    console.log(t("hooksPathBelegtHilfe"));
    return;
  }
  if (hooks.lage.art === "entfaellt") {
    console.log(t("hooksPathEntfaellt", { grund: hooks.lage.grund }));
    return;
  }
  if (hooks.lage.art === "schon gesetzt") {
    console.log(t("hooksPathSchon"));
    return;
  }
  console.log(t("hooksPathNicht"));
}

// Bestehende workflow.config.json als Update-Defaults laden und das alte provider-Feld
// (Rueckwaertskompatibilitaet) auf codeHost/issueTracker migrieren.
function loadExistingConfig(configPath) {
  let existingConfig = {};
  if (existsSync(configPath)) {
    try {
      // Gelesen unter den deutschen Namen (Issue #1438), geschrieben mit den englischen (Issue #1728).
      existingConfig = normalisiereConfig(JSON.parse(readFileSync(configPath, "utf-8"))).config;
      console.log(t("configGefunden"));
    } catch {
      console.warn(t("configUnlesbar"));
    }
  }
  if (existingConfig.provider && !existingConfig.codeHost) existingConfig.codeHost = existingConfig.provider;
  if (existingConfig.provider && !existingConfig.issueTracker) existingConfig.issueTracker = existingConfig.provider;
  return existingConfig;
}

// .gitignore-Block fuer .claude/ (Issue #208).
//
// workflow.config.json gehoert ins Repository: buildChecks, columns, Branch-Namen und
// Tracker muessen fuer alle gleich sein. Lag die Datei ausserhalb, hatte jeder seine
// eigene Fassung — und eine abweichende columns-Fassung fuehrt nicht zu einem Fehler,
// sondern zu einer leeren Issue-Liste.
//
// Die erste Zeile MUSS `.claude/*` lauten, nicht `.claude/`: Git wertet ein
// !-Negationsmuster nicht aus, wenn das Verzeichnis selbst ausgeschlossen ist — es
// betritt es gar nicht erst. Mit `.claude/` bliebe die Negation wirkungslos, und der
// Fehler faehlt sich an wie "vergessen zu committen".
//
// Die Zeilen nach der Negation sind formal redundant (`.claude/*` deckt sie), stehen
// aber bewusst da: Sie machen lesbar, dass persoenliche Config, Metadaten-Cache und die
// laufend geschriebenen Protokolle absichtlich draussen bleiben. Die Berichte der
// Wirksamkeits-Auswertung (`.claude/wirksamkeit.md`, `.claude/wirksamkeit.json`) haben
// hier keinen eigenen Eintrag: Aufgezaehlt werden die Zustandsdateien, die der Prozess
// fortschreibt, nicht jedes erzeugte Ergebnis.
// Die beiden Kopfzeilen stehen in der Sprache des Projekts (Issue #1455); erkannt wird der
// Block an der Negationszeile, nicht an ihnen.
const gitignoreBlock = () => [
  t("gitignoreKopf1"),
  t("gitignoreKopf2"),
  ".claude/*",
  "!.claude/workflow.config.json",
  ".claude/workflow.config.local.json",
  ".claude/board-meta-cache.json",
  ".claude/wegmarken.tsv",
  // Die beiden Protokolle der Wirksamkeits-Auswertung (Plan #782): Ohne Eintrag laegen
  // sie in jedem frisch installierten Projekt als Reste im Arbeitsbaum.
  // SYNC: Geschrieben werden sie anderswo — `ausfuehrungen.tsv` in kit/checks.mjs,
  // `bewegungen.tsv` in kit/board.mjs (`bewegungSchreiben`). Wer einen der Namen dort
  // aendert, aendert ihn hier mit, sonst faellt die Datei aus dem .gitignore.
  ".claude/ausfuehrungen.tsv",
  ".claude/bewegungen.tsv",
  // Protokoll und Vorschlagsstand der Befund-Auswertung (Plan #797). Dieselbe Regel wie
  // eine Zeile darueber: Aufgezaehlt werden die fortgeschriebenen Zustandsdateien. Die
  // Berichte `.claude/befunde.md` und `.claude/befunde.json` stehen bewusst nicht hier,
  // sondern sind wie die der Wirksamkeit ueber `.claude/*` gedeckt.
  ".claude/befunde.tsv",
  ".claude/befunde-vorschlaege.json",
  ".claude/sitzung-meldung.json",
  // Die Stuecke eines gestueckelten Abschlussberichts (Issue #1022). Sie liegen nur bis
  // zum gelungenen Abschluss von `issue report`, nach einem Fehlschlag aber bis zur
  // Wiederholung — ein fortgeschriebener Zustand wie die Protokolle darueber.
  // SYNC: `BERICHTE_ORDNER` in kit/board.mjs schreibt sie, kit/night.mjs nimmt sie im
  // Rest-Guard aus. Wer den Namen dort aendert, aendert ihn hier mit.
  ".claude/berichte/",
];

// '.claude/'-Regeln im projektlokalen .gitignore sicherstellen (idempotent).
function ensureProjectGitignore() {
  const gitignorePath = resolve(".gitignore");
  const content = existsSync(gitignorePath) ? readFileSync(gitignorePath, "utf-8") : "";
  const lines = content.split(/\r?\n/);
  const trimmed = lines.map((l) => l.trim());

  if (trimmed.includes("!.claude/workflow.config.json")) {
    console.log(t("gitignoreVorhanden"));
    return;
  }

  // Eine handgepflegte .claude-Konfiguration nicht still umschreiben — das waere ein
  // Uebergriff. Nur melden, welcher Block empfohlen ist.
  const eigeneRegeln = trimmed.some((l) => l.startsWith(".claude/") && l !== ".claude/") ||
    trimmed.some((l) => l.startsWith("!.claude/"));
  if (eigeneRegeln) {
    console.log(t("gitignoreEigene"));
    console.log(t("gitignoreEmpfohlen"));
    for (const zeile of gitignoreBlock()) console.log(`    ${zeile}`);
    return;
  }

  const alteZeile = trimmed.indexOf(".claude/");
  if (alteZeile !== -1) {
    // Migration: ersetzen, nicht ergaenzen. Bliebe `.claude/` stehen, liefe die
    // Negation aus dem oben genannten Grund ins Leere.
    lines.splice(alteZeile, 1, ...gitignoreBlock());
    if (schreibeKitDatei(gitignorePath, lines.join("\n"))) console.log(t("gitignoreErsetzt"));
    return;
  }

  const block = gitignoreBlock().join("\n") + "\n";
  const next = content.endsWith("\n") || content === "" ? content + block : content + "\n" + block;
  if (schreibeKitDatei(gitignorePath, next)) console.log(t("gitignoreEingetragen"));
}

// --- Der Sitzungs-Melder an den Hooks von Claude Code (Issue #735, Plan E22) ---
//
// Der Melder aus Issue #734 existiert, aber niemand ruft ihn. Gerufen wird er von
// Claude Code selbst: `Stop` nach jedem Zug (fortschreibend, im Melder auf eine
// Meldung je fuenf Minuten gedrosselt) und `SessionEnd` am Ende der Sitzung
// (abschliessend, mit `--complete`).
//
// In der PROJEKT-settings.json und NICHT in den Nutzer-Einstellungen unter
// `~/.claude`: Die Erfassung ist projektgebunden — das Zielprojekt kommt aus der
// Bindung des Tokens im Arbeitsverzeichnis —, eine nutzerweite Einstellung meldete
// aus jedem Verzeichnis, auch aus jedem fremden.
//
// Eingetragen wird ohne Bedingung auf den Tracker. Ob ueberhaupt gemeldet wird,
// entscheidet der Melder selbst und sagt es auch ('kein-board', 'kein-token'). Die
// Frage im Installer ein zweites Mal zu beantworten, erzeugte eine zweite Wahrheit:
// Wer `issueTracker` spaeter von Hand auf 'toolbox' stellt, haette dann stumm keinen
// Hook und suchte den Fehler am Melder.
//
// Dazu der Bash-Pruef-Hook (Issue #995): Seit Claude Code 2.1.277 hebt eine Pipe oder
// Umleitung die Ausnahme aus `sandbox.excludedCommands` auf. Der Hook weist solche
// Zeilen vor dem Lauf ab und nennt die richtige Form.
//
// Und der Schreib-Pruef-Hook (Issue #1740): Im Modus auto hat eine Runner-Session eine Datei
// unter `permissions.deny` mit `Edit` geaendert. Der Hook weist Edit, Write und NotebookEdit an
// den Schreibsperren des Projekts selbst ab. Einen deutschen Vorgaenger hat er nicht, darum
// fehlt ihm `alt`.
//
// `kennung` und `alt` sind das, woran ein Eintrag erkennbar ist — unabhaengig davon, welcher
// Pfad davorsteht und welche Schalter dahinter. Ein Vergleich auf das ganze Kommando
// verdoppelte den Eintrag, sobald jemand den Aufruf von Hand angepasst hat.
//
// Eingetragen werden die englischen Namen (Issue #1556, Plan #1548 E1). Ein bestehendes Projekt
// traegt noch den deutschen Aufruf `alt`, den board.mjs seit Issue #1557 abweist: Das Update
// ersetzt darin nur dieses Stueck durch `kennung` (Issue #1569, Plan #1548 E10) — Pfad, Schalter
// und die uebrigen Felder des Eintrags bleiben.
const SITZUNG_HOOKS = [
  { event: "SessionEnd", command: "node .claude/kit/board.mjs session report --complete", kennung: "board.mjs session report", alt: "board.mjs sitzung melden" },
  { event: "Stop", command: "node .claude/kit/board.mjs session report", kennung: "board.mjs session report", alt: "board.mjs sitzung melden" },
  { event: "PreToolUse", matcher: "Bash", command: "node .claude/kit/board.mjs hook bash-check", kennung: "board.mjs hook bash-check", alt: "board.mjs hook bash-pruefen" },
  { event: "PreToolUse", matcher: "Edit|Write|NotebookEdit", command: "node .claude/kit/board.mjs hook write-check", kennung: "board.mjs hook write-check" },
];

/**
 * Ein Hook-Eintrag nach dem Umschreiben: der erste erkannte mit englischem Befehl, jeder weitere
 * erkannte `null` — ein Doppel liesse den Melder doppelt laufen. `stand` merkt sich, ob einer
 * gefunden und ob etwas geaendert wurde.
 */
function umgeschriebenerHook(h, { kennung, alt }, stand) {
  const befehl = typeof h?.command === "string" ? h.command : "";
  const alterName = Boolean(alt) && befehl.includes(alt);
  if (!befehl.includes(kennung) && !alterName) return h;
  if (stand.gefunden) {
    stand.geaendert = true;
    return null;
  }
  stand.gefunden = true;
  if (!alterName) return h;
  stand.geaendert = true;
  return { ...h, command: befehl.replace(alt, kennung) };
}

/**
 * Die Matcher-Gruppen eines Ereignisses mit genau einem Eintrag des Kits in englischem Namen —
 * sofern es ihn schon gab. Eine Gruppe, die nur ein entferntes Doppel trug, entfaellt.
 */
function schreibeHooksUm(gruppen, hook) {
  const stand = { gefunden: false, geaendert: false };
  const neu = [];
  for (const g of gruppen) {
    if (!Array.isArray(g?.hooks)) {
      neu.push(g);
      continue;
    }
    const hooks = g.hooks.map((h) => umgeschriebenerHook(h, hook, stand)).filter((h) => h !== null);
    if (hooks.length > 0 || g.hooks.length === 0) neu.push({ ...g, hooks });
  }
  return { gruppen: neu, ...stand };
}

/** Sagt, was von Hand nachzutragen ist — der Rueckfall, wenn wir die Datei nicht anfassen. */
function meldeHooksVonHand(pfad, grund) {
  console.log(t("hooksVonHand", { pfad, grund }));
  console.log(t("hooksVonHandHilfe"));
  for (const { event, matcher, command } of SITZUNG_HOOKS) {
    const zusatz = matcher ? ` (${matcher})` : "";
    console.log(`    ${event}${zusatz}: ${command}`);
  }
}

/**
 * Liest die bestehende settings.json — oder sagt, warum sie unangetastet bleibt.
 *
 * Eigene Funktion, damit `ensureSitzungsHooks` unter der Komplexitaetsschwelle bleibt,
 * die dieses Repo seit Issue #404 haelt.
 */
function liesSettings(pfad) {
  if (!existsSync(pfad)) return {};
  try {
    const gelesen = JSON.parse(readFileSync(pfad, "utf-8"));
    if (!gelesen || typeof gelesen !== "object" || Array.isArray(gelesen)) throw new Error("kein Objekt");
    return gelesen;
  } catch {
    // Nicht ueberschreiben: Was dort steht, ist Handarbeit — und was wir nicht lesen
    // koennen, koennen wir auch nicht erhalten.
    return null;
  }
}

/**
 * Schreibt die Eintraege des Kits in `hooks` auf die englischen Namen um und haengt die
 * fehlenden an. Liefert die Ereignisse, die neu dazukamen, und die, die umgeschrieben wurden.
 */
function ordneHooksEin(hooks) {
  const neu = [];
  const umgeschrieben = [];
  for (const hook of SITZUNG_HOOKS) {
    const { event, matcher, command } = hook;
    const { gruppen, gefunden, geaendert } = schreibeHooksUm(Array.isArray(hooks[event]) ? hooks[event] : [], hook);
    if (geaendert) umgeschrieben.push(event);
    if (gefunden) {
      hooks[event] = gruppen;
      continue;
    }
    // Angehaengt, nicht vorangestellt: Ein vorhandener Hook des Projekts behaelt seine
    // Reihenfolge, und unserer ist der letzte.
    const gruppe = matcher ? { matcher, hooks: [{ type: "command", command }] } : { hooks: [{ type: "command", command }] };
    hooks[event] = [...gruppen, gruppe];
    neu.push(event);
  }
  return { neu, umgeschrieben };
}

/**
 * Traegt den Melder in die `hooks` von `.claude/settings.json` ein (idempotent).
 *
 * ERGAENZT, ersetzt nicht: settings.json ist die geteilte Projektdatei von Claude Code
 * und traegt `env`, `sandbox` und `permissions`. Sie zu ueberschreiben naehme dem
 * Projekt seine Einstellungen — und fremde Hook-Eintraege gleich mit.
 *
 * Ist nichts nachzutragen, wird die Datei NICHT geschrieben: Ein zweiter Lauf soll sie
 * byteweise so lassen, wie sie ist, und nicht bloss inhaltsgleich neu formatieren.
 */
function ensureSitzungsHooks(targetBase) {
  const pfad = join(targetBase, "settings.json");
  const settings = liesSettings(pfad);
  if (settings === null) {
    meldeHooksVonHand(pfad, t("keinJsonObjekt"));
    return;
  }

  const bestand = settings.hooks;
  const hooks = (bestand && typeof bestand === "object" && !Array.isArray(bestand)) ? bestand : {};
  const { neu, umgeschrieben } = ordneHooksEin(hooks);
  if (neu.length === 0 && umgeschrieben.length === 0) {
    console.log(t("hooksSchon", { pfad }));
    return;
  }

  settings.hooks = hooks;
  if (!schreibeKitDatei(pfad, JSON.stringify(settings, null, 2) + "\n")) return;
  if (umgeschrieben.length > 0) console.log(t("hooksUmgeschrieben", { pfad, ereignisse: umgeschrieben.join(", ") }));
  if (neu.length > 0) console.log(t("hooksEingetragen", { pfad, ereignisse: neu.join(", ") }));
}

// --- Stellen, die der Mensch selbst aendern muss (Issue #1570, Plan #1548 E11) ---
//
// Was das Update nicht selbst umschreibt, nennt es: eigene Sandbox-Ausnahmen, Paket-Skripte und
// Zeitplaene, die das Kit unter einem alten Namen rufen. Gesucht wird lesend an festen Orten —
// `.claude/settings.json`, `.claude/settings.local.json`, die `scripts` der `package.json` und
// `crontab -l`. Nicht durchsucht werden LaunchAgents und fremde Verzeichnisse: `crontab -l` ist
// ein Kommando ohne Pfadwissen, sie verlangten geratene Pfade ausserhalb des Projekts.

// Die frueheren Dateinamen der Kommandos (Issues #1559, #1560, #1563).
const ALTE_DATEIEN = Object.freeze({ "befunde.mjs": "findings.mjs", "aufwand.mjs": "effort.mjs",
  "wirksamkeit.mjs": "effectiveness.mjs", "einstellungen.mjs": "settings.mjs" });
// SYNC: DEUTSCHE_FLAGS in kit/night/grundlagen.mjs (Issue #1565).
const ALTE_NIGHT_FLAGS = Object.freeze({ "--kette": "--chain", "--pruefen": "--check", "--waechter": "--watcher" });

const rx = (s) => s.replaceAll(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);
const wort = (s) => String.raw`(?<![\w.-])${rx(s)}(?![\w-])`;
const einer = (namen) => `(?:${namen.map(rx).join("|")})`;

/**
 * Die Regeln alt → neu, laengste Form zuerst: Ein Fund, der in einem frueheren liegt, zaehlt
 * nicht — die alte Achse samt altem Befehl ist ein Fund, nicht zusaetzlich die alte Achse allein. Eine
 * Regel mit `kommando` gilt nur in einer Zeichenkette, die dieses Kommando nennt: `--teil` ist
 * allein kein Aufruf des Kits.
 */
function altnamenRegeln() {
  const { achsen, befehle, schutz, optionen, werte } = ALTNAMEN;
  const achsNamen = (en) => [en, ...Object.keys(achsen).filter((de) => achsen[de] === en)];
  const optNamen = (en) => [en, ...Object.keys(optionen).filter((de) => optionen[de] === en)];
  const regeln = [];
  for (const [option, ebene] of Object.entries(werte)) {
    for (const [de, en] of Object.entries(ebene)) {
      regeln.push({ alt: `--${option} ${de}`, neu: `--${option} ${en}`, kommando: "board.mjs",
        muster: String.raw`(?<![\w-])--${einer(optNamen(option))}[ =]${rx(de)}(?![\w-])` });
    }
  }
  for (const [de, en] of Object.entries(schutz)) {
    regeln.push({ alt: `board.mjs code protection ${de}`, neu: `board.mjs code protection ${en}`,
      muster: String.raw`board\.mjs\s+code\s+${einer(["protection", ...Object.keys(befehle.code)])}\s+${rx(de)}(?![\w-])` });
  }
  for (const [achse, ebene] of Object.entries(befehle)) {
    for (const [de, en] of Object.entries(ebene)) {
      regeln.push({ alt: `board.mjs ${achse} ${de}`, neu: `board.mjs ${achse} ${en}`,
        muster: String.raw`board\.mjs\s+${einer(achsNamen(achse))}\s+${rx(de)}(?![\w-])` });
    }
  }
  for (const [de, en] of Object.entries(achsen)) {
    regeln.push({ alt: `board.mjs ${de}`, neu: `board.mjs ${en}`, muster: String.raw`board\.mjs\s+${rx(de)}(?![\w-])` });
  }
  for (const [de, en] of Object.entries(optionen)) {
    regeln.push({ alt: `--${de}`, neu: `--${en}`, kommando: "board.mjs", muster: wort(`--${de}`) });
  }
  for (const [de, en] of Object.entries(ALTE_NIGHT_FLAGS)) {
    regeln.push({ alt: de, neu: en, kommando: "night.mjs", muster: wort(de) });
  }
  for (const [de, en] of Object.entries(ALTE_DATEIEN)) {
    regeln.push({ alt: de, neu: en, muster: String.raw`(?<![\w.-])${rx(de)}` });
  }
  return regeln.map((r) => ({ ...r, muster: new RegExp(r.muster, "g") }));
}

const ALTNAMEN_REGELN = altnamenRegeln();

/** Die Treffer der Regeln in einer Zeichenkette, je Treffer `{ regel, alt }` in der Reihenfolge des Texts. */
function altnamenTreffer(zeichenkette) {
  const belegt = [];
  const treffer = [];
  for (const regel of ALTNAMEN_REGELN) {
    if (regel.kommando && !zeichenkette.includes(regel.kommando)) continue;
    for (const m of zeichenkette.matchAll(regel.muster)) {
      const von = m.index;
      const bis = von + m[0].length;
      if (belegt.some(([a, b]) => von >= a && bis <= b)) continue;
      belegt.push([von, bis]);
      treffer.push({ von, regel, alt: m[0] });
    }
  }
  return treffer.sort((a, b) => a.von - b.von);
}

/** Die Funde alter Namen in einer Zeichenkette, je Fund `{ ort, alt, neu }`; `alt` ist der Text, wie er dort steht. */
export function altnamenFunde(ort, zeichenkette) {
  return altnamenTreffer(zeichenkette).map(({ regel, alt }) => ({ ort, alt, neu: regel.neu }));
}

/** Jede Zeichenkette eines JSON-Werts mit ihrem Pfad (`sandbox.excludedCommands[1]`). */
function zeichenketten(wert, pfad = "", aus = []) {
  if (typeof wert === "string") aus.push([pfad, wert]);
  else if (Array.isArray(wert)) wert.forEach((w, i) => zeichenketten(w, `${pfad}[${i}]`, aus));
  else if (wert && typeof wert === "object") {
    for (const [k, w] of Object.entries(wert)) zeichenketten(w, pfad ? `${pfad}.${k}` : k, aus);
  }
  return aus;
}

/** Die Zeilen von `crontab -l`; fehlt das Kommando oder gibt es keinen Zeitplan, keine. */
function crontabZeilen() {
  const res = spawnSync("crontab", ["-l"], { encoding: "utf-8", timeout: 10_000 });
  if (res.error || res.status !== 0) return [];
  return String(res.stdout ?? "").split(/\r?\n/);
}

/** Die Zeichenketten der festen Orte, je `[ort, zeichenkette]`; gelesen wird nur. */
function fundOrte() {
  const orte = [];
  for (const datei of [".claude/settings.json", ".claude/settings.local.json"]) {
    for (const [pfad, s] of zeichenketten(liesSettings(resolve(datei)) ?? {})) orte.push([`${datei}: ${pfad}`, s]);
  }
  const paket = liesSettings(resolve("package.json"));
  for (const [pfad, s] of zeichenketten(paket?.scripts ?? {}, "scripts")) orte.push([`package.json: ${pfad}`, s]);
  crontabZeilen().forEach((zeile, i) => orte.push([t("crontabOrt", { zeile: i + 1 }), zeile]));
  return orte;
}

/** Alle Fundstellen an den festen Orten; gelesen wird nur. */
function sucheFundstellen() {
  return fundOrte().flatMap(([ort, s]) => altnamenFunde(ort, s));
}

/**
 * Die Schlussmeldung des projektlokalen Laufs: jede Fundstelle, danach immer die vollstaendige
 * Tabelle alt → neu. Der globale Install hat kein Projekt, in dem er suchen koennte.
 */
function meldeSelbstZuAendern(scope) {
  if (scope !== "projekt") return;
  console.log(t("selbstKopf"));
  const funde = sucheFundstellen();
  if (funde.length === 0) console.log(t("selbstKeine"));
  for (const f of funde) console.log(t("selbstFund", f));
  console.log(t("selbstTabelle"));
  for (const r of ALTNAMEN_REGELN) {
    const kommando = r.kommando ? ` (${r.kommando})` : "";
    console.log(`    ${r.alt} → ${r.neu}${kommando}`);
  }
  console.log(t("selbstAusserhalb"));
}

// Schreibt die Teile von night.mjs und board.mjs nach `night/` und `board/` des Kit-Verzeichnisses
// (Issue #1209, Plan #1199 E1), die Texttabellen der Module nach texte/ (Issue #1524), die Messung der Verflechtung nach checks/
// (Issue #1714). Die Einstiege laden ihre Teile aus diesen Unterverzeichnissen.
// Das Verzeichnis entsteht auch leer: Dann gibt es noch keinen Teil, und ein neuer Teil
// braucht spaeter keine Aenderung an dieser Stelle.
// Die Pruefrollen in rollen/ kommen in der Projektsprache (Issue #1464); die Rueckgabe ist ihre
// Berichtszeile.
// Ein Teil mit leerer Konstante ist ein fehlender Pro-Teil (Issue #1861): kein Ordner, keine Zeile.
function schreibeTeile(kitDir, sprache) {
  for (const [teil, blob] of [["night", KIT_NIGHT_B64], ["board", KIT_BOARD_B64], ["texte", KIT_TEXTE_B64], ["checks", KIT_CHECKS_B64]]) {
    if (blob !== "") schreibeTeil(kitDir, teil, blobJson(blob));
  }
  return schreibeRollen(kitDir, sprache);
}

function schreibeTeil(kitDir, teil, dateien) {
  const teilDir = join(kitDir, teil);
  mkdirSync(teilDir, { recursive: true });
  for (const [datei, inhalt] of Object.entries(dateien)) {
    schreibeKitDatei(join(teilDir, datei), inhalt);
  }
  console.log(t("teileGeschrieben", { teil, anzahl: Object.keys(dateien).length, pfad: teilDir }));
  return teilDir;
}

function schreibeRollen(kitDir, sprache) {
  const { dateien, rueckfall } = spracheWaehlen(blobJson(KIT_ROLLEN_B64), blobJson(KIT_ROLLEN_EN_B64), sprache);
  return rueckfallZeilen(schreibeTeil(kitDir, "rollen", dateien), rueckfall);
}

// Schreibt die Agenten nach agents/ des Ziels (Issue #1377, Plan #1375 A2), nach dem Muster
// von copySkills: Die Namen kommen aus dem Blob, eine Liste gibt es nicht. Claude Code liest
// <targetBase>/agents/ global wie projektweit.
function copyAgents(targetDir, sprache) {
  mkdirSync(targetDir, { recursive: true });
  const { dateien, rueckfall } = spracheWaehlen(blobJson(AGENTS_B64), blobJson(AGENTS_EN_B64), sprache);
  for (const [datei, inhalt] of Object.entries(dateien)) {
    schreibeKitDatei(join(targetDir, datei), inhalt);
  }
  console.log(t("agentenGeschrieben", { anzahl: Object.keys(dateien).length, pfad: targetDir }));
  return rueckfallZeilen(targetDir, rueckfall);
}

// Nennt am Schluss der Installation, was deutsch blieb; eine eigene Funktion, damit main()
// unter der Komplexitaetsschwelle bleibt (Issue #404).
function meldeRueckfall(zeilen) {
  if (zeilen.length > 0) console.log(`\n${zeilen.join("\n")}`);
}

/**
 * Was die Umstellung in der neuen Sprache ablegt (Issue #1464, Plan #1420 E12): Regeltexte,
 * Pruefer und Pruefrollen — dieselben Wege wie die Installation, sonst nichts aus dem Kit.
 * Skills tauscht sie nicht, die gibt es seit Issue #1566 nur in einer Fassung. Die Rueckgabe
 * sind die Berichtszeilen dessen, was deutsch bleibt.
 */
function schreibeSprachfassungen(targetBase, sprache) {
  return [
    ...schreibeRegeltexte(targetBase, sprache),
    ...copyAgents(join(targetBase, "agents"), sprache),
    ...schreibeRollen(join(targetBase, "kit"), sprache),
  ];
}

/**
 * Die Abbruchmeldung unter nativem Windows (Issue #1276, Plan #1265 E3). "ab" und nicht
 * "seit": Der `npx`-Weg zieht `main`, die Abweisung kann kurz vor dem Release wirken.
 */
const WINDOWS_ABWEISUNG = Object.freeze(["windowsNicht", "windowsWsl"]);

/**
 * Die einzige Stelle, an der das Kit natives Windows noch erkennt (Fachplan #1264,
 * Kriterien 6 und 9; Plan #1265 E1, E2, E4). Node meldet unter Git Bash, MSYS und
 * Cygwin-Node `win32`, unter WSL2 `linux`: Die eine Bedingung weist genau die Wege ab,
 * die das Kit nicht unterstuetzt, und laesst WSL2 durch. Liefert die Zeilen der
 * Abbruchmeldung oder `null`; die Plattform ist ein Parameter, damit die Abweisung auf
 * jedem Host pruefbar ist.
 */
export function windowsAbweisung(plattform = process.platform) {
  return plattform === "win32" ? WINDOWS_ABWEISUNG.map((k) => t(k)) : null;
}

// Was vor jeder Frage endet: natives Windows und --version. Eigene Funktion, damit main()
// unter der Komplexitaetsschwelle bleibt (Issue #404).
function vorabEnden() {
  // Vor allem anderen, auch vor --version und dem Lesen von stdin (E1): Unter nativem
  // Windows geschieht nichts am Projekt, und keine Ausgabe steht vor der Meldung.
  const abweisung = windowsAbweisung();
  if (abweisung) {
    process.stderr.write(`${abweisung.join("\n")}\n`);
    process.exit(1);
  }

  if (process.argv.includes("--version")) {
    console.log(`claude-workflow-kit install.mjs v${VERSION}`);
    process.exit(0);
  }
  if (process.argv.includes("--help")) {
    console.log(HILFE);
    process.exit(0);
  }
  altnameAbweisen(process.argv.slice(2));
}

// Die Hilfe ist englisch, in jedem Projekt (Issue #1569, Fachplan #1527 Kriterium 1).
const HILFE = [
  "Usage:",
  "  node install.mjs                     install the kit (asks its questions), or update it without questions",
  "  node install.mjs --reconfigure       update and ask all questions again, the config as default",
  "  node install.mjs --language de|en    switch an existing project to another language",
  "  node install.mjs --protection        set up only the protection of the main branch",
  "  node install.mjs --version           print the version",
  "  node install.mjs --help              print this help",
].join("\n");

// Die frueheren deutschen Optionen (Issue #1569, Plan #1548 E8): Es gibt sie nicht mehr, auch
// nicht fuer eine Uebergangszeit. Sie enden mit dem Namen, der jetzt gilt, bevor etwas geschieht.
const DEUTSCHE_OPTIONEN = Object.freeze({ "--schutz": "--protection", "--sprache": "--language" });

function altnameAbweisen(argv) {
  for (const argument of argv) {
    const name = argument.split("=")[0];
    if (Object.hasOwn(DEUTSCHE_OPTIONEN, name)) throw new Error(t("altname", { name, englisch: DEUTSCHE_OPTIONEN[name] }));
  }
}

// --- Das Update ohne Fragen (Issue #1804) ---
//
// Steht das Kit schon im Projekt, kopiert der Installer nur: keine Frage, kein stdin, keine
// Probe fuer den Schutz, kein Eingriff in core.hooksPath. Einstellungen aendert `--reconfigure`,
// den Schutz `--protection`. Die globale Installation bleibt beim Ablauf mit Fragen.

/** Ein Update ist ein Lauf in einem Projekt mit Config, ohne `--reconfigure` und ohne `--protection`. */
function istUpdate(argv) {
  if (argv.includes("--reconfigure") || argv.includes("--protection")) return false;
  return existsSync(resolve(".claude", "workflow.config.json"));
}

/**
 * Die Felder aus DEFAULTS, die in der Config fehlen. Das Reviewer-Paar bleibt ein Paar: Steht
 * eines der beiden Felder, kommt das andere nicht dazu (Issue #433).
 */
export function neueFelder(existingConfig, defaults = DEFAULTS) {
  const paar = ["reviewModel", "reviewCommand"];
  const paarSteht = paar.some((feld) => Object.hasOwn(existingConfig, feld));
  return Object.fromEntries(Object.entries(defaults).filter(([feld]) =>
    !Object.hasOwn(existingConfig, feld) && !(paarSteht && paar.includes(feld))));
}

/** Die Config des Projekts, wie die Werkzeuge sie lesen; eine unlesbare bricht das Update ab. */
function leseUpdateConfig(configPfad) {
  let roh;
  try {
    roh = JSON.parse(readFileSync(configPfad, "utf-8"));
  } catch {
    roh = null;
  }
  if (roh === null || typeof roh !== "object" || Array.isArray(roh)) throw new Error(t("updateUnlesbar"));
  const { config } = normalisiereConfig(roh);
  if (config.provider && !config.codeHost) config.codeHost = config.provider;
  if (config.provider && !config.issueTracker) config.issueTracker = config.provider;
  delete config.provider;
  return { roh, config };
}

/**
 * Die Versionsbloecke des mitgereisten Changelogs (Issue #1847, Plan #1830 E8), neueste zuerst:
 * je Block Version, Eintraege, die Schritte unter `### Was du noch tun musst` — `null`, wenn
 * der Block die Ueberschrift nicht traegt — und die Zeilen unter `### Umbenannt` (Issue #1848).
 * `[Unreleased]` gehoert zu keiner Fassung und faellt weg.
 */
export function changelogBloecke(text) {
  const bloecke = [];
  // Ein Teil ist die Liste, in die die Punkte darunter gehoeren, oder null.
  let teil = null;
  for (const zeile of text.split("\n")) {
    if (zeile.startsWith("## ")) {
      const version = /^## \[(\d+\.\d+\.\d+)\]/.exec(zeile)?.[1];
      if (version) bloecke.push({ version, eintraege: [], schritte: null, umbenannt: [] });
      teil = version ? bloecke.at(-1).eintraege : null;
    } else if (zeile.startsWith("### ")) {
      teil = unterabschnitt(bloecke.at(-1), zeile);
    } else if (teil && zeile.startsWith("- ")) {
      teil.push(zeile.slice(2).trim());
    }
  }
  return bloecke;
}

/** Die Liste fuer `### Was du noch tun musst` oder `### Umbenannt`, null fuer jede andere Ueberschrift. */
function unterabschnitt(block, zeile) {
  if (!block) return null;
  const kopf = zeile.trim();
  if (kopf === "### Umbenannt") return block.umbenannt;
  if (kopf !== "### Was du noch tun musst") return null;
  block.schritte = [];
  return block.schritte;
}

/** Die Bloecke nach `vorher` bis einschliesslich `nachher`, aelteste zuerst. */
export function bloeckeZwischen(bloecke, vorher, nachher) {
  return bloecke
    .filter((b) => vergleicheVersion(b.version, vorher) > 0 && vergleicheVersion(b.version, nachher) <= 0)
    .toReversed();
}

/** Die Fragen aus PFLICHT_OHNE_VORGABE, die die Config nicht beantwortet, in der Projektsprache. */
function offeneFragen(bestand, pflicht = PFLICHT_OHNE_VORGABE) {
  const sprache = prozessSprache();
  return pflicht
    .filter(({ feld }) => !Object.hasOwn(bestand, feld))
    .map(({ feld, frage }) => ({ feld, frage: frage[sprache] ?? frage.de }));
}

/** Der Pfad hinter `--result-file` oder null; die Option ohne Pfad bricht ab. */
function ergebnisPfad(argv) {
  const gleich = argv.find((a) => a.startsWith("--result-file="));
  if (gleich) return resolve(gleich.slice("--result-file=".length));
  const i = argv.indexOf("--result-file");
  if (i < 0) return null;
  if (!argv[i + 1] || argv[i + 1].startsWith("--")) throw new Error(t("ergebnisOhnePfad"));
  return resolve(argv[i + 1]);
}

/**
 * Die Ergebnisdatei fuer `update run` und `update all` (Plan #1830 E5). `geschuetzt` nennt die
 * Dateien, die der Mensch geaendert hat und das Update nicht anfasste (#1849).
 */
function schreibeErgebnis(pfad, ergebnis) {
  if (!pfad) return;
  writeFileSync(pfad, JSON.stringify({ geschuetzt: [], offeneFragen: [], ...ergebnis }, null, 2) + "\n", "utf-8");
}

/** Die Eintraege der Bloecke je Fassung, oder der Satz, warum keine dastehen. */
function changelogZeilen(vorher, bloecke) {
  if (!vorher) return [t("changelogUnbekannt")];
  if (bloecke.length === 0) return [t("changelogLeer")];
  return bloecke.flatMap((b) => [t("changelogFassung", { version: b.version }), ...b.eintraege.map((e) => `  - ${e}`)]);
}

/**
 * „Was du noch tun musst“ (Kriterium 4, 5): die Schritte der Fassungen dazwischen, je Fassung
 * ohne den Abschnitt der Verweis auf ihre Eintraege, die neuen Fragen mit Vorgabe (E12), zuletzt
 * das Committen — ohne Schritt steht nur das.
 */
function tunZeilen(bloecke, neu, nachher) {
  const zeilen = bloecke.flatMap((b) => (b.schritte === null
    ? [t("tunOhneAbschnitt", { version: b.version })]
    : b.schritte.map((schritt) => t("tunSchritt", { version: b.version, schritt }))));
  for (const [feld, wert] of Object.entries(neu)) {
    // Die Strenge nennt, wie man sie aendert: ueber die Einstellungen, nur durch den Menschen (Issue #2114).
    zeilen.push(t(feld === "strenge" ? "tunStrenge" : "tunFeld", { feld: englischerName(feld), wert: JSON.stringify(wert) }));
  }
  for (const pfad of geschuetzteDateien()) zeilen.push(t("tunAbgleich", { pfad }));
  zeilen.push(t("tunCommitten", { nachher }));
  return zeilen;
}

const englischerName = (feld) => Object.keys(benenneUm({ [feld]: 0 }, "en").config)[0];

// --- Umbenannt in der Meldung des Updates (Issue #1848, Plan #1830 E9) ---
// Drei Quellen, je alter Name einmal: `### Umbenannt` der Fassungen dazwischen, die beim
// Schreiben umbenannten Einstellungen (config-namen.mjs) und das Register ALTNAMEN, dessen
// Tabelle hier aufgeht. Gesucht wird lesend mit `git grep` ueber die versionierten Dateien ohne
// die, die der Installer schreibt, dazu an den festen Orten aus fundOrte(). Angepasst wird nichts.

// SYNC: UMBENANNT_RE in tools/changelog.mjs, dort ohne den Spiegelstrich.
const UMBENANNT_ZEILE = /^(skill|befehl|label|einstellung) `([^`]+)` -> `([^`]+)`$/;
// Die Art je Sprache; ausserhalb von TEXTE, weil "einstellung" auch in "einstellungen.mjs" steht.
const ART_NAMEN = Object.freeze({
  de: { skill: "skill", befehl: "befehl", label: "label", einstellung: "einstellung" },
  en: { skill: "skill", befehl: "command", label: "label", einstellung: "setting" },
});

/**
 * Die Umbenennungen, je alter Name einmal, je `{ art, alt, neu }`; eine aus ALTNAMEN traegt dazu
 * ihre `regel` und gegebenenfalls ihr `kommando`, auch wenn der Changelog sie schon nennt.
 */
function umbenennungen(bloecke, einstellungen) {
  const liste = new Map();
  const dazu = (eintrag) => {
    const vorhanden = liste.get(eintrag.alt);
    if (!vorhanden) liste.set(eintrag.alt, eintrag);
    else if (eintrag.regel) Object.assign(vorhanden, { regel: eintrag.regel, kommando: eintrag.kommando });
  };
  for (const zeile of bloecke.flatMap((b) => b.umbenannt)) {
    const m = UMBENANNT_ZEILE.exec(zeile);
    if (m) dazu({ art: m[1], alt: m[2], neu: m[3] });
  }
  for (const { alt, neu } of einstellungen) dazu({ art: "einstellung", alt, neu });
  for (const regel of ALTNAMEN_REGELN) dazu({ art: "befehl", alt: regel.alt, neu: regel.neu, regel, kommando: regel.kommando });
  return [...liste.values()];
}

/**
 * Die Pfade, die der Installer schreibt, als Ausschluss fuer `git grep`: Sie tragen nach dem
 * Update die neuen Namen. Die Settings und `package.json` durchsucht fundOrte() genauer.
 */
function installerPfade() {
  return [".claude/kit/**", ".claude/skills/**", ".claude/agents/**", ".claude/CLAUDE-*.md", ".claude/workflow.config.json",
    ".claude/kontext.config.json", ".claude/settings.json", ".claude/settings.local.json", ".githooks/pre-commit", ".gitignore",
    ...Object.keys(blobJson(KIT_BIN_B64))].map((pfad) => `:(exclude,glob)${pfad}`);
}

/** Die versionierten Dateien, in denen `alt` als Wort steht; eine Regel mit Kommando verlangt es in derselben Zeile. */
function versionierteFunde({ alt, kommando }) {
  const muster = kommando ? ["-e", alt, "--and", "-e", kommando] : ["-e", alt];
  const res = cliSpawn("git", ["grep", "-l", "-z", "-I", "-w", "-F", ...muster, "--", ".", ...installerPfade()], "INSTALL_GIT_FAKE", { encoding: "utf-8" });
  if (res.error || res.status !== 0) return [];
  return String(res.stdout ?? "").split("\0").filter(Boolean);
}

/** Die Fundstellen einer Umbenennung: versionierte Dateien, dann die festen Orte. */
function fundstellenVon(eintrag, orte, imRepo) {
  const wort = new RegExp(String.raw`(?<!\w)${rx(eintrag.alt)}(?!\w)`);
  const amOrt = orte.filter(({ s, regeln }) => (eintrag.regel ? regeln.has(eintrag.regel) : wort.test(s))).map(({ ort }) => ort);
  return [...(imRepo ? versionierteFunde(eintrag) : []), ...amOrt];
}

/** Der Block „Umbenannt“: zuerst jede Umbenennung mit Fundstellen, darunter die uebrigen. */
function umbenanntZeilen(eintraege, imRepo) {
  const orte = fundOrte().map(([ort, s]) => ({ ort, s, regeln: new Set(altnamenTreffer(s).map((x) => x.regel)) }));
  const arten = ART_NAMEN[prozessSprache()] ?? ART_NAMEN.de;
  const zeilen = [t("umbenanntKopf")];
  const ohne = [];
  for (const eintrag of eintraege) {
    const werte = { art: arten[eintrag.art], alt: eintrag.alt, neu: eintrag.neu, kommando: eintrag.kommando ? ` (${eintrag.kommando})` : "" };
    const funde = fundstellenVon(eintrag, orte, imRepo);
    if (funde.length === 0) ohne.push(t("umbenanntOhneFundZeile", werte));
    else zeilen.push(t("umbenanntZeile", werte), ...funde.map((ort) => t("umbenanntFund", { ort })));
  }
  if (ohne.length > 0) zeilen.push(t("umbenanntOhneFund"), ...ohne);
  if (!imRepo) zeilen.push(t("umbenanntNichtGesucht"));
  zeilen.push(t("selbstAusserhalb"));
  return zeilen;
}

/**
 * Die Meldung nach dem Update in der Reihenfolge von Kriterium 4 (Issue #1847): Versionen,
 * Changelog-Eintraege, Umbenennungen (#1848), uncommittete Dateien, „Was du noch tun musst“.
 * Die geschuetzten Dateien und die Sicherung (#1849) stehen nach den uncommitteten.
 */
function meldeUpdate({ vorher, nachher, neu, workspaceVorher, einstellungen }) {
  const bloecke = vorher ? bloeckeZwischen(changelogBloecke(kitChangelog()), vorher, nachher) : [];
  console.log(t("meldungVersion", { vorher: vorher ?? t("vorherUnbekannt"), nachher }));
  console.log(t("meldungChangelog"));
  console.log(changelogZeilen(vorher, bloecke).join("\n"));
  console.log(t("meldungUmbenannt"));
  console.log(umbenanntZeilen(umbenennungen(bloecke, einstellungen), imGitRepo()).join("\n"));
  meldeWorkspace(workspaceVorher);
  const schutz = schrankeZeilen();
  if (schutz.length > 0) console.log(`\n${schutz.join("\n")}`);
  meldeProDateien();
  console.log(t("meldungTun"));
  console.log(tunZeilen(bloecke, neu, nachher).join("\n"));
}

// --- Die Ausgabe eines 5.x-Projekts (Issue #1927, Plan #1918 E8, E9) ---
//
// Ein 5.x-Projekt wird beim Update Community, wenn niemand Pro waehlt. Es sieht das vor dem ersten
// Schreiben, samt den Teilen aus 5.x, die ab 6.0.0 Pro sind (Issue #2019, Plan #2008 A6). Der
// Runner ist seit Issue #2012 Community: Der Stummel, der bis dahin an die Stelle eines alten
// Runners trat, entfaellt; einen vorhandenen ersetzt der echte night.mjs wie jede Kit-Datei.

/** Der Weg zu Pro fuer ein Projekt, das (noch) kein `--edition` kennt (E8). */
const proWegText = () => t("proWeg", { repo: PRO_REPO, url: proSeite(prozessSprache()) });

/** Die Namen der Pro-Teile aus PRO_FUNKTIONEN und PRO_TEILE, jeder einmal, in der Sprache des Laufs. */
const proTeilNamen = () => [...new Set([...PRO_FUNKTIONEN, ...Object.keys(PRO_TEILE)])].map((teil) => t(`proTeil_${teil}`)).join(", ");

/**
 * Die Anzeige vor dem ersten Schreiben (E9): bei einer Kopie unter 6.0.0 Ausgabe und Version, in
 * Community dazu die Teile, die ab 6.0.0 Pro sind (Issue #2019, #1995 Kriterium 6).
 */
function meldeAusgabeVorUpdate(vorher) {
  if (vorher && vergleicheVersion(vorher, ERSTE_GETRENNTE_FASSUNG) >= 0) return;
  console.log(t("updateAusgabe", { ausgabe: AUSGABE === "community" ? "Community" : "Pro", version: VERSION }));
  if (AUSGABE === "community") console.log(t("updateProTeile", { teile: proTeilNamen(), url: proSeite(prozessSprache()) }));
}

/** Der Ort einer Pro-Datei im Projekt: die Skripte aus kit/bin/ liegen im Projektordner, der Rest unter .claude/. */
const proOrt = (pfad) => (pfad.startsWith("kit/bin/") ? pfad.slice("kit/bin/".length) : `.claude/${pfad}`);

/** Steht die Pro-Datei im Projekt? Ein Skript nur mit Skript-Kennung. */
function proDateiSteht(ort, pfad) {
  if (!existsSync(resolve(ort))) return false;
  return !pfad.startsWith("kit/bin/") || readFileSync(resolve(ort), "utf-8").includes(SKRIPT_KENNUNG);
}

/** Was ein Muster aus PRO_TEILE im Projekt trifft: ein Verzeichnis (`/` am Ende) oder Dateien mit `*`. */
function musterImProjekt(muster) {
  if (muster.endsWith("/")) return existsSync(resolve(muster)) ? [muster] : [];
  const ordner = dirname(muster);
  const [vor, nach] = basename(muster).split("*");
  if (!existsSync(resolve(ordner))) return [];
  return readdirSync(resolve(ordner)).filter((d) => d.startsWith(vor) && d.endsWith(nach)).sort(vergleicheText).map((d) => `${ordner}/${d}`);
}

/** Die Pro-Dateien und Pro-Beigaben, die im Projekt stehen geblieben sind, relativ zum Projekt. */
function stehengebliebeneProDateien() {
  const gefunden = [];
  for (const { dateien, muster, installiert } of Object.values(PRO_TEILE)) {
    if (installiert === false) continue;
    gefunden.push(...dateien.filter((pfad) => proDateiSteht(proOrt(pfad), pfad)).map(proOrt));
    for (const m of muster) gefunden.push(...musterImProjekt(proOrt(m)));
  }
  gefunden.push(...PRO_BEIGABEN.map((datei) => `.claude/kit/${datei}`).filter((ort) => existsSync(resolve(ort))));
  return gefunden;
}

/** In Community die Zeile zu stehengebliebenen Pro-Dateien mit dem Weg zu Pro (E10). */
function meldeProDateien() {
  if (AUSGABE !== "community") return;
  const dateien = stehengebliebeneProDateien();
  if (dateien.length > 0) console.log(`\n${t("proDateien", { dateien: dateien.join(", "), weg: proWegText() })}`);
}

/** Die PID aus einer Sperre (Zahl) oder einem Puls (JSON mit `pid`), sonst null. */
function pidAus(roh) {
  if (!roh.startsWith("{")) return Number(roh);
  try {
    return JSON.parse(roh).pid;
  } catch {
    return null;
  }
}

/**
 * Traegt der Laufbericht `.claude/night-run-<lauf>.json` einen Abschluss (Issue #2169)? Dann ist der
 * Lauf beendet, gleich was seine PID meldet.
 * SYNC: Kopie von laufBeendet in kit/board/update.mjs.
 */
function laufBeendet(wurzel, lauf) {
  try {
    return JSON.parse(readFileSync(join(wurzel, ".claude", `night-run-${lauf}.json`), "utf-8"))?.abschluss != null;
  } catch {
    return false;
  }
}

/**
 * Laeuft im Projekt ein Runner (Issue #2020, Plan #2008 A5)? Die Sperre `.claude/night-umsetzung.lock`
 * traegt die PID als Zahl, ein Puls `.claude/lauf/*.puls` als JSON-Feld `pid`. Es zaehlt nur eine
 * lebende PID; eine nach einem Absturz liegengebliebene Datei blockiert nicht, ein Puls eines beendeten
 * Laufs ebenso wenig.
 * SYNC: Kopie von runnerLaeuft in kit/board/update.mjs. Die Pruefung steht bewusst zweimal: `update
 * run` startet den Installer bei laufendem Runner gar nicht, und der Installer wird auch allein aufgerufen.
 */
export function runnerLaeuft(wurzel, kill = process.kill) {
  const lauf = join(wurzel, ".claude", "lauf");
  const pulse = existsSync(lauf) ? readdirSync(lauf).filter((n) => n.endsWith(".puls")).map((n) => join(lauf, n)) : [];
  return [join(wurzel, ".claude", "night-umsetzung.lock"), ...pulse].some((pfad) => {
    if (pfad.endsWith(".puls") && laufBeendet(wurzel, basename(pfad, ".puls"))) return false;
    let roh;
    try {
      roh = readFileSync(pfad, "utf-8");
    } catch {
      return false;
    }
    const pid = pidAus(roh.trim());
    if (!Number.isInteger(pid) || pid <= 0) return false;
    try {
      kill(pid, 0);
      return true;
    } catch (e) {
      return e?.code === "EPERM";
    }
  });
}

/**
 * Was vor dem ersten Schreiben endet (E12, E13): ein laufender Runner (Issue #2020, ohne Fehler),
 * eine neuere installierte Kopie, eine unlesbare Config, eine Frage ohne Vorgabe. Liefert die
 * gelesene Config oder `ende`, wenn der Lauf endet.
 */
function updateVorpruefung(configTarget, ergebnis) {
  const { vorher, nachher } = ergebnis;
  if (runnerLaeuft(resolve("."))) {
    const grund = t("updateRunner");
    console.log(grund);
    return { ende: { ...ergebnis, ergebnis: "uebersprungen", grund }, ohneFehler: true };
  }
  if (vorher && vergleicheVersion(vorher, nachher) > 0) {
    console.error(t("updateRueckschritt", { vorher, nachher }));
    return { ende: { ...ergebnis, ergebnis: "rueckschritt" } };
  }
  let gelesen;
  try {
    gelesen = leseUpdateConfig(configTarget);
  } catch (e) {
    return { ende: { ...ergebnis, ergebnis: "fehlgeschlagen", grund: e.message }, fehler: e };
  }
  const offen = offeneFragen(gelesen.config);
  if (offen.length > 0) {
    console.error(t("updatePflicht"));
    for (const { feld, frage } of offen) console.error(t("updatePflichtFrage", { feld, frage }));
    console.error(t("updatePflichtWeiter"));
    return { ende: { ...ergebnis, ergebnis: "fehlgeschlagen", offeneFragen: offen } };
  }
  return gelesen;
}

async function updateModus() {
  console.log("\n=== claude-workflow-kit Installer ===\n");
  console.log(t("updateKopf"));
  const ergebnisDatei = ergebnisPfad(process.argv.slice(2));
  const stand = { vorher: installierteVersion(resolve(".")), nachher: VERSION };
  const targetBase = resolve(".claude");
  const configTarget = join(targetBase, "workflow.config.json");
  const vorpruefung = updateVorpruefung(configTarget, stand);
  if (vorpruefung.ende) {
    schreibeErgebnis(ergebnisDatei, vorpruefung.ende);
    if (vorpruefung.fehler) throw vorpruefung.fehler;
    if (!vorpruefung.ohneFehler) process.exitCode = 1;
    return;
  }
  meldeAusgabeVorUpdate(stand.vorher);
  const { roh, config: bestand } = vorpruefung;
  const neu = neueFelder(bestand);
  // Bestehende Felder zuerst, in ihrer Reihenfolge: Ohne neue Felder bleibt die Datei byte-gleich.
  const config = { ...bestand, ...neu };
  const projektSpracheLauf = prozessSprache();
  const workspaceVorher = workspaceStand();
  starteSchranke(workspaceVorher);

  console.log(t("kopiereSkills", { pfad: join(targetBase, "skills") }));
  const skillAnzahl = copySkills(join(targetBase, "skills"));
  const alteEntfernt = entferneAlteSkills(join(targetBase, "skills"));
  const rueckfall = [];

  // Bleibt die Config geschuetzt, hat das Update keine Vorgabe uebernommen.
  if (schreibeKitDatei(configTarget, JSON.stringify(zumSchreiben(config, roh), null, 2) + "\n")) console.log(t("configGeschrieben", { pfad: configTarget }));
  else for (const feld of Object.keys(neu)) delete neu[feld];
  for (const [feld, wert] of Object.entries(neu)) {
    console.log(t("neuesFeld", { feld: englischerName(feld), wert: JSON.stringify(wert) }));
  }
  const lokal = migriereLokaleConfig(targetBase);
  meldeUmbenannt(false, roh, lokal);
  if (config.spec) console.log(t("specHinweis"));

  const kitDir = schreibeKitDateien(targetBase, projektSpracheLauf, rueckfall);
  setzeSzenarienAb(kitDir, configTarget, "projekt");
  meldeBereichsvorschlag(kitDir, "projekt", false, config);
  schreibeCommitGate("projekt", null);
  const skripte = schreibeSkripte("projekt");
  ensureProjectGitignore();
  ensureSkripteGitignore(skripte);
  ensureSitzungsHooks(targetBase);

  const rl = { close: () => {} };
  await schliesse({ scope: "projekt", config, rl, configTarget, workspaceVorher: null, skillAnzahl, alteEntfernt, rueckfall, fragen: false, update: true });
  meldeUpdate({ ...stand, neu, workspaceVorher, einstellungen: [...umbenannteEinstellungen(roh), ...lokal] });
  schreibeErgebnis(ergebnisDatei, { ...stand, ergebnis: "aktualisiert", geschuetzt: geschuetzteDateien() });
}

async function main() {
  // Die Sprache steht ab hier fest, aus der Config vor jeder Aenderung (Issue #1455): Die
  // Umstellung berichtet in der Sprache, die das Projekt bis dahin hatte, und ein neues
  // Projekt legt sie mit der Antwort auf die Sprachfrage neu fest.
  prozessSprache();
  vorabEnden();

  // Die Umstellung fragt nichts und liest darum kein stdin (Issue #1438).
  const umstellung = umstellSprache(process.argv.slice(2));
  if (umstellung) {
    console.log(t("umstellungKopf", { ziel: umstellung }));
    umstellModus(umstellung);
    return;
  }

  // Das Update fragt nichts und liest darum kein stdin (Issue #1804).
  if (istUpdate(process.argv)) {
    await updateModus();
    return;
  }

  await loadPipedLines();
  const rl = IST_TTY
    ? createInterface({ input: process.stdin, output: process.stdout })
    : { close: () => {} };

  if (process.argv.includes("--protection")) {
    console.log(t("schutzKopf"));
    await schutzModus(rl);
    rl.close();
    return;
  }

  const sprache = await kopfMitSprache(rl);

  // Frage 1: global oder projekt
  const scope = await promptScope(rl);
  schranke.global = scope === "global";

  // Bestehende Config als Defaults laden (Update-Modus)
  const existingConfigPath = scope === "global"
    ? join(homedir(), ".claude", "workflow.config.json")
    : resolve(".claude", "workflow.config.json");
  const sprachfeld = sprachfeldNeu(sprache, existingConfigPath);
  const ersteinrichtung = !existsSync(existingConfigPath);
  const roh = leseRoh(existingConfigPath);
  const existingConfig = loadExistingConfig(existingConfigPath);
  spracheDesLaufs(sprache, existingConfig);
  const D = { ...DEFAULTS, ...existingConfig };

  // Frage 2: codeHost
  const codeHost = await askWithDefault(
    rl,
    t("frageCodeHost"),
    D.codeHost,
    "codeHost"
  );

  // Schutzfragen (nur projektlokal bei GitHub, Issue #1409): Build-Dienst, Vorschlag, Pruefzweig.
  const schutzZweig = await frageSchutz(rl, scope, codeHost, existingConfig);

  // Frage 3: issueTracker
  const issueTracker = await askWithDefault(
    rl,
    t("frageTracker"),
    D.issueTracker ?? codeHost,
    "issueTracker"
  );

  // Frage 4: mainBranch
  const mainBranch = await askWithDefault(rl, t("frageMain"), D.mainBranch);

  // Frage 5: productionBranch
  const productionBranch = await askWithDefault(rl, t("frageProduction"), D.productionBranch);

  // Frage 6: reviewScope
  const reviewScope = await askWithDefault(
    rl,
    t("frageReviewScope"),
    D.reviewScope,
    "reviewScope"
  );

  // Frage 7 und 8: das Reviewer-Paar — genau eines von beiden (Issue #433).
  const { reviewModel, reviewCommand } = await promptReviewerPaar(rl, D, existingConfig);

  // Frage 9 (nur projektlokal): die Strenge, Vorschlag die bestehende oder `normal` (Issue #2114).
  const strenge = await frageStrenge(rl, scope, D.strenge);

  // Frage 10 (nur projektlokal, und nur wenn core.hooksPath frei ist): das
  // Commit-Gate einhaengen (Issue #473).
  const hooks = await frageHooksPath(rl, scope);

  // Frage 11 (nur projektlokal, die letzte der projektlokalen Folge): die Bereiche
  // und je vorhandener Pruefung ihre Zuordnung (Issue #1009).
  const bereiche = await frageBereiche(rl, scope, existingConfig, ersteinrichtung);

  // Frage 12 (nur projektlokal, nach den Bereichen): die Vorgaben des Projekttyps (Issue #2115).
  const projekttyp = await frageProjekttyp(rl, scope, bereiche?.buildChecks ?? existingConfig.buildChecks);

  // Frage 9 (nur bei globalem Install): Vault-Pfad für kontext.config.json
  let vaultPath = "";
  if (scope === "global") {
    const raw = await ask(rl, t("frageVault"));
    vaultPath = raw.trim();
  }

  // --- Pfade berechnen ---
  const targetBase = scope === "global"
    ? join(homedir(), ".claude")
    : resolve(".claude");
  const skillsTarget = join(targetBase, "skills");
  const configTarget = join(targetBase, "workflow.config.json");
  // Die Sprache dieses Laufs steht seit spracheDesLaufs fest; Regeltexte, Pruefer und
  // Pruefrollen kommen in ihr, was davon deutsch bleibt, nennt der Schluss (Issue #1464). Die
  // Skills haben eine Fassung (Issue #1566).
  const projektSpracheLauf = prozessSprache();

  // Vor dem ersten Schreiben: Was jetzt schon liegt, nennt der Schlussblock als vorgefunden.
  const workspaceVorher = workspaceStand();

  // --- Skills kopieren ---
  console.log(t("kopiereSkills", { pfad: skillsTarget }));
  const skillAnzahl = copySkills(skillsTarget);
  const alteEntfernt = entferneAlteSkills(skillsTarget);
  const rueckfall = [];

  // --- Config schreiben ---
  // Basis sind die DEFAULTS (fuellen echte Luecken), darueber die bestehende Config
  // (nicht abgefragte Felder wie buildChecks, toolbox, github oder unbekannte
  // Zusatzfelder bleiben erhalten, #125), zuoberst die abgefragten Werte.
  const config = {
    ...DEFAULTS,
    ...existingConfig,
    codeHost,
    issueTracker,
    mainBranch,
    productionBranch,
    reviewScope,
    ...strenge,
    ...bereiche,
  };
  if (projekttyp) config.buildChecks = projekttyp.vorgaben.buildChecks;
  // Das alte provider-Feld ist beim Laden auf codeHost/issueTracker migriert worden
  // und wird nicht zurueckgeschrieben.
  delete config.provider;
  Object.assign(config, sprachfeld);
  // Das Reviewer-Paar wird als Paar geschrieben, nicht feldweise gespreadet: Genau
  // eines der beiden Felder steht in der Datei, das andere wird entfernt. Beide
  // Vorlagen fuellen sonst ein bewusst geleertes reviewModel wieder auf —
  // `schema.defaults.reviewModel` ueber den DEFAULTS-Spread und die Bestandsconfig
  // ueber ihren eigenen (Issue #433).
  if (reviewModel) {
    config.reviewModel = reviewModel;
    delete config.reviewCommand;
  } else {
    config.reviewCommand = reviewCommand;
    delete config.reviewModel;
  }
  haltVerzichtFest(config, hooks);
  if (schreibeKitDatei(configTarget, JSON.stringify(zumSchreiben(config, roh), null, 2) + "\n")) console.log(t("configGeschrieben", { pfad: configTarget }));
  meldeUmbenannt(ersteinrichtung, roh, migriereLokaleConfig(targetBase));
  projekttypAnwenden(projekttyp);
  // Der spec-Block ist eine Altlast aus Spec-Driven Development (entfallen mit
  // Idee #813, Plan #825). Ein vorhandener Block kommt ueber den
  // existingConfig-Spread unveraendert mit — kein Werkzeug liest ihn mehr, und der
  // Installer sagt das genau einmal, statt ihn still mitzuschleppen oder
  // eigenmaechtig zu entfernen (A4).
  if (config.spec) console.log(t("specHinweis"));

  // --- kontext.config.json schreiben (nur bei globalem Install mit Vault-Pfad) ---
  if (scope === "global" && vaultPath) {
    const kontextConfig = {
      vault: vaultPath,
      always: ["Index.md", "Profil.md"],
      projectDocs: ["CLAUDE-*", ".claude/CLAUDE-*"],
    };
    const kontextConfigTarget = join(targetBase, "kontext.config.json");
    schreibeKitDatei(kontextConfigTarget, JSON.stringify(kontextConfig, null, 2) + "\n");
    console.log(t("geschrieben", { datei: "kontext.config.json", pfad: kontextConfigTarget }));
  }

  const kitDir = schreibeKitDateien(targetBase, projektSpracheLauf, rueckfall);
  richteSchutzEin(kitDir, configTarget, schutzZweig);
  setzeSzenarienAb(kitDir, configTarget, scope);
  meldeBereichsvorschlag(kitDir, scope, ersteinrichtung, config);

  schreibeCommitGate(scope, hooks);
  const skripte = schreibeSkripte(scope);

  // --- .gitignore ergänzen und den Melder einhaengen (nur projektlokal) ---
  if (scope === "projekt") {
    ensureProjectGitignore();
    ensureSkripteGitignore(skripte);
    ensureSitzungsHooks(targetBase);
  }

  await schliesse({ scope, config, rl, configTarget, workspaceVorher, skillAnzahl, alteEntfernt, rueckfall, fragen: true });
}

/**
 * Legt Regeltexte, Beispiel-Config, die Kit-Dateien, ihre Teile und die Agenten ab und sammelt
 * die Rueckfaelle in `rueckfall`. Gemeinsam fuer Einrichtung und Update (Issue #1804). Liefert
 * das Kit-Verzeichnis.
 */
function schreibeKitDateien(targetBase, projektSpracheLauf, rueckfall) {
  // --- CLAUDE-workflow.md und die Gate-Register ablegen ---
  rueckfall.push(...schreibeRegeltexte(targetBase, projektSpracheLauf));

  // --- Beispiel-Config ablegen ---
  schreibeBeispiel(targetBase, projektSpracheLauf);

  // --- board.mjs ausschreiben ---
  const kitDir = join(targetBase, "kit");
  mkdirSync(kitDir, { recursive: true });
  schreibeKitModul(kitDir, "board.mjs", BOARD_MJS_B64);

  // --- night.mjs ausschreiben (Runner, #131) ---
  schreibeKitModul(kitDir, "night.mjs", NIGHT_MJS_B64);

  // --- checks.mjs ausschreiben (Pruef-Auswahl, #425) ---
  // Die implement-Skills und /push-main rufen es als .claude/kit/checks.mjs auf;
  // ohne diesen Block laege es nur im Kit-Repo und der Aufruf ginge ins Leere.
  schreibeKitModul(kitDir, "checks.mjs", CHECKS_MJS_B64);

  // --- preise.mjs ausschreiben (Preistabelle des Sitzungs-Melders, #734) ---
  // board.mjs laedt sie als Nachbardatei. Fehlt sie, meldet der Melder den Verbrauch
  // in Token weiter, aber ohne Dollarbetrag — kein Fehler, nur eine Angabe weniger.
  schreibeKitModul(kitDir, "preise.mjs", PREISE_MJS_B64);

  // --- effort.mjs ausschreiben (Aufwands-Auswertung, #750; seit #1560 unter dem englischen Namen) ---
  // Der Runner ruft es am Ende jedes Laufs, /push-main vor dem Veroeffentlichen.
  // Ohne diesen Block laege es nur im Kit-Repo und beide Aufrufe gingen ins Leere.
  schreibeKitModul(kitDir, "effort.mjs", EFFORT_MJS_B64);

  // --- effectiveness.mjs ausschreiben (Wirksamkeits-Auswertung, #787; seit #1560 unter dem
  // englischen Namen) ---
  // Liest das Ausfuehrungsprotokoll von checks.mjs (#785). Ohne diesen Block bekaeme
  // ein bestehendes Projekt die Auswertung nicht, und kein Folgepaket koennte
  // `node .claude/kit/effectiveness.mjs` aufrufen.
  schreibeKitModul(kitDir, "effectiveness.mjs", EFFECTIVENESS_MJS_B64);

  // --- findings.mjs ausschreiben (Form und Arten der Funde, #799; seit #1559 unter dem
  // englischen Namen) ---
  // Der Regeltext verweist fuer die Artenliste auf `node .claude/kit/findings.mjs kinds`,
  // und die Pruef-Skills rufen `findings check`. Ohne diesen Block ginge beides in
  // jedem Zielprojekt ins Leere.
  schreibeKitModul(kitDir, "findings.mjs", FINDINGS_MJS_B64);

  // --- worktree.mjs ausschreiben (Worktree der Release-Skills, #929) ---
  // `/push-main` und `/merge-production` legen damit ihren eigenen Worktree an, statt im
  // Haupt-Working-Tree zu bauen, in dem gleichzeitig der Runner arbeiten kann.
  // Es ruft night.mjs als Nachbardatei — beide liegen hier zusammen.
  schreibeKitModul(kitDir, "worktree.mjs", WORKTREE_MJS_B64);

  // --- Die Lizenztexte der Ausgabe (Issue #1922, Plan #1918 E11) ---
  // Neben den Kit-Dateien, die sie betreffen. Ohne Pro ist LICENSE_PRO_B64 leer, und
  // schreibeKitModul uebergeht LICENSE-PRO.
  schreibeKitModul(kitDir, "LICENSE", LICENSE_B64);
  schreibeKitModul(kitDir, "LICENSE-PRO", LICENSE_PRO_B64);

  rueckfall.push(...schreibeTeile(kitDir, projektSpracheLauf), ...copyAgents(join(targetBase, "agents"), projektSpracheLauf));
  return kitDir;
}

/**
 * Schreibt eine Datei des Kits aus ihrer Base64-Konstante nach `kitDir` und meldet sie. Eine
 * leere Konstante ist ein fehlender Pro-Teil (Issue #1861): nichts schreiben, nichts melden.
 */
function schreibeKitModul(kitDir, datei, b64) {
  if (b64 === "") return;
  const pfad = join(kitDir, datei);
  if (schreibeKitDatei(pfad, Buffer.from(b64, "base64").toString("utf-8"))) console.log(t("geschrieben", { datei, pfad }));
}

/**
 * Der Schlussblock, gemeinsam fuer Einrichtung und Update (Issue #1804). Ohne `fragen` (Update)
 * entfaellt die Frage nach den GitLab-Labels; der Hinweis zum Login bleibt. Im `update` geht
 * die Liste der alten Namen im Block „Umbenannt“ der Meldung auf (Issue #1848).
 */
async function schliesse({ scope, config, rl, configTarget, workspaceVorher, skillAnzahl, alteEntfernt, rueckfall, fragen, update = false }) {
  const { codeHost, issueTracker } = config;
  trageProjektEin(scope);
  meldeRueckfall(rueckfall);
  // Nach dem Umschreiben der Hooks: Was danach noch einen alten Namen ruft, aendert der Mensch.
  if (!update) meldeSelbstZuAendern(scope);
  meldeEntfallenenSchritt(alteEntfernt);
  console.log(t("fertig"));
  // In Community nennt das Ende Ausgabe und Version; einen Pruefweg ueber doctor gibt es dort
  // nicht (Issue #2019, #1995 Kriterium 9).
  if (AUSGABE === "community") console.log(t("fertigAusgabe", { ausgabe: "Community", version: VERSION }));
  console.log(t("neueSession"));
  // Gezaehlt statt behauptet: Das Zahlwort stand hier zweimal falsch (zuletzt
  // "dreizehn" bei fuenfzehn Skills) — es wurde bei jedem neuen Skill vergessen.
  console.log(t("skillsInHelp", { anzahl: skillAnzahl }));
  if (scope === "projekt") {
    // Ohne diesen Hinweis bleibt die Datei ungetrackt liegen und niemand merkt es —
    // bis zwei Entwickler unterschiedliche buildChecks fahren (Issue #208).
    console.log(t("committen"));
  }
  if (codeHost === "gitlab" || issueTracker === "gitlab") {
    console.log(t("gitlabLogin"));
    if (fragen) await setupGitLabLabels(rl);
  } else if (codeHost === "github" || issueTracker === "github") {
    console.log(t("githubLogin"));
  }
  // rl erst hier schliessen — setupGitLabLabels fragt interaktiv nach
  rl.close();
  console.log(t("naechsterSchritt"));
  console.log(t("pfad", { pfad: configTarget }));
  meldeIssueReview(config);
  starteKartenpruefung(scope, config);
  // Als allerletzte Ausgabe, nach der Label-Einrichtung: Weiter oben rutschte sie aus dem Bild.
  meldeWorkspace(workspaceVorher);
}

/**
 * Startet nach dem Einspielen einmal die Pruefung je Karte (Issue #2156, Plan #2145 E20): Da sie
 * alles seit `origin/<mainBranch>` nimmt (E4), prueft der erste Lauf den ganzen unveroeffentlichten
 * Stand. Nur im Projekt, in Pro mit dem Teil `card-check` und mit `origin/<mainBranch>` — ohne ihn
 * fehlt die Basis wie in `abschlussDesLaufs` (kit/night/kitstand.mjs). Ruft `board.mjs update` den
 * Installer, startet es die Pruefung selbst und setzt `KIT_INSTALL_OHNE_KARTENPRUEFUNG`, damit sie
 * nicht zweimal beginnt. Ein Fehlschlag ist eine Zeile und haelt nichts auf.
 * `NIGHT_KARTENPRUEFUNG_CMD` ersetzt den Start durch ein Shell-Kommando, allein fuer die Ablauftests.
 * SYNC: dieselbe Bedingung wie `kartenpruefungNachUpdate` in kit/board/update.mjs.
 */
function starteKartenpruefung(scope, config) {
  if (scope !== "projekt" || AUSGABE === "community" || process.env.KIT_INSTALL_OHNE_KARTENPRUEFUNG) return;
  const night = resolve(".claude", "kit", "night.mjs");
  if (!existsSync(resolve(".claude", "kit", "night", "kartenpruefung.mjs"))) return;
  const mainBranch = config.mainBranch || "main";
  if (gitAntwort("rev-parse", "--verify", "-q", `refs/remotes/origin/${mainBranch}^{commit}`) === null) return;
  const ersatz = process.env.NIGHT_KARTENPRUEFUNG_CMD;
  const [bin, argv] = ersatz ? ["sh", ["-c", ersatz]] : [process.execPath, [night, "--card-check", "--detach"]];
  const res = spawnSync(bin, argv, { stdio: ["ignore", "ignore", "pipe"], encoding: "utf-8", timeout: 60_000 });
  if (!res.error && res.status === 0) {
    console.log(t("kartenpruefungGestartet"));
    return;
  }
  const grund = res.error?.message ?? [(res.stderr || "").trim(), `Exit ${res.status}`].filter(Boolean).join(" — ");
  console.log(t("kartenpruefungNichtGestartet", { grund }));
}

/**
 * Traegt das Projekt in die Projektliste dieses Rechners ein, aus der `update all` liest (Issue
 * #1843, Plan #1830 E4, E14) — nur im Projekt-Scope, nicht im Kit-Repo und nur, wenn der Installer
 * die Projektliste traegt (Issue #2014). Ein Fehlschlag warnt und haelt nicht auf: Das Projekt ist
 * installiert, ihm fehlt nur der Eintrag.
 */
function trageProjektEin(scope) {
  const projekt = resolve(".");
  if (eintragen === null || scope !== "projekt" || istKitRepo(projekt)) return;
  const res = eintragen(projekt, VERSION, { ausgabe: AUSGABE });
  if (!res.ok) console.error(t("projektlisteFehler", { datei: res.datei, fehler: res.fehler }));
}

/**
 * Der Rat, den issueReview-Block zu uebernehmen — nur ohne Reviewer: Ein Projekt, das den Block
 * schon traegt, bekaeme sonst bei jedem Update eine Meldung zu einer Einstellung, die gar nicht
 * fehlt (Issue #1734).
 */
function meldeIssueReview(config) {
  // Seit Issue #2019 auch in Community: Sie prueft mit mehreren Modellen wie Pro (Plan #2008 A6).
  if ((config.issueReview?.reviewers?.length ?? 0) === 0) console.log(t("issueReview"));
}

// --- Die Schreibschranke (Issue #1849, Plan #1830 E10, E11) ---
//
// Jede Datei des Kits im Projekt geht ueber schreibeKitDatei oder entferneKitDatei. Im Update
// bleibt eine Datei, die der Mensch geaendert hat und die das Update ebenfalls aendern muesste,
// unveraendert. Geaendert ist eine versionierte Datei, die `git status --porcelain` vor dem Lauf
// nennt, und eine unversionierte, deren SHA-256 vom Datei-Stand abweicht: Die Kopie unter
// `.claude/` ist nicht versioniert, `git status` saehe dort nichts. Weicht der neue Inhalt auch
// vom alten Kit-Inhalt ab, nennt die Meldung die Datei. Den Datei-Stand schreibt jeder Lauf am
// Ende; eine geschuetzte Datei behaelt ihren alten Eintrag. Ohne Eintrag im Datei-Stand — beim
// ersten Update gibt es keinen — sichert das Update eine unversionierte Datei, bevor es sie mit
// anderem Inhalt ueberschreibt oder loescht.

const DATEI_STAND = join(".claude", "kit-dateien.json");
const SICHERUNG_ORDNER = join(".claude", "update-sicherung");

const schranke = {
  schuetzen: false,
  stand: null,
  versioniert: new Set(),
  geaendert: new Set(),
  geschrieben: new Set(),
  geschuetzt: [],
  sicherung: null,
  beruehrt: false,
  // Die globale Installation schreibt nach HOME und hat keinen Datei-Stand im Projekt, auch
  // wenn HOME unter dem Arbeitsverzeichnis liegt.
  global: false,
};

// Nach Codepunkten wie vergleicheText in kit/checks.mjs: Der Datei-Stand sieht auf jedem Rechner gleich aus.
const vergleicheText = (a, b) => (a < b ? -1 : Number(a > b));

const hashVon = (inhalt) => (inhalt === null ? null : createHash("sha256").update(inhalt).digest("hex"));

/** Der Pfad relativ zum Projekt mit `/`, oder null ausserhalb (die globale Installation). */
function projektPfad(pfad) {
  if (schranke.global) return null;
  const rel = relative(process.cwd(), pfad);
  return rel === "" || rel.startsWith("..") || isAbsolute(rel) ? null : rel.split(sep).join("/");
}

function dateiStand() {
  if (!schranke.stand) {
    try {
      schranke.stand = { ...JSON.parse(readFileSync(resolve(DATEI_STAND), "utf-8")).dateien };
    } catch {
      schranke.stand = {};
    }
  }
  return schranke.stand;
}

/**
 * Schaltet den Schutz fuer das Update ein. `workspaceVorher` sind die Zeilen von `git status
 * --porcelain` vor dem ersten Schreiben; versioniert ist, was `git ls-files` kennt. Ohne git ist
 * jede Datei unversioniert und der Datei-Stand ihr einziger Massstab.
 */
function starteSchranke(workspaceVorher) {
  schranke.schuetzen = true;
  schranke.geaendert = new Set((workspaceVorher ?? []).filter((z) => !z.startsWith("??")).map((z) => z.slice(3).split(" -> ").at(-1)));
  const res = cliSpawn("git", ["ls-files", "-z"], "INSTALL_GIT_FAKE", { encoding: "utf-8" });
  schranke.versioniert = new Set(res.error || res.status !== 0 ? [] : String(res.stdout ?? "").split("\0").filter(Boolean));
}

/** Der Hash des alten Kit-Inhalts einer versionierten Datei aus HEAD, oder undefined. */
function hashInHead(rel) {
  const res = cliSpawn("git", ["show", `HEAD:${rel}`], "INSTALL_GIT_FAKE", {});
  return res.error || res.status !== 0 ? undefined : hashVon(res.stdout);
}

/**
 * Was mit einer Datei geschieht, die neu `neu` tragen soll (null: geloescht): "gleich",
 * "schreiben", "sichern" (schreiben, die jetzige vorher sichern), "bleibt" (geaendert, das
 * Update braechte nichts Neues) oder "melden" (geaendert, und das Update braechte Neues).
 */
function urteil(rel, jetzt, neu) {
  if (jetzt === null ? neu === null : neu !== null && jetzt.equals(neu)) return "gleich";
  if (!schranke.schuetzen || schranke.geschrieben.has(rel)) return "schreiben";
  if (schranke.versioniert.has(rel)) {
    if (!schranke.geaendert.has(rel)) return "schreiben";
    return hashInHead(rel) === hashVon(neu) ? "bleibt" : "melden";
  }
  const alt = dateiStand()[rel];
  if (alt === undefined) return jetzt === null ? "schreiben" : "sichern";
  if (jetzt === null || alt === hashVon(jetzt)) return "schreiben";
  return alt === hashVon(neu) ? "bleibt" : "melden";
}

function sichere(rel, jetzt) {
  schranke.sicherung ??= join(SICHERUNG_ORDNER, new Date().toISOString().replaceAll(/[:.]/g, "-"));
  const ziel = resolve(schranke.sicherung, rel);
  mkdirSync(dirname(ziel), { recursive: true });
  writeFileSync(ziel, jetzt);
}

/** Traegt die Wirkung einer geschriebenen oder geloeschten Datei in den Datei-Stand ein. */
function vermerke(rel, neu) {
  schranke.beruehrt = true;
  schranke.geschrieben.add(rel);
  if (neu === null) delete dateiStand()[rel];
  else dateiStand()[rel] = hashVon(neu);
}

const gesperrt = (ergebnis) => ergebnis === "bleibt" || ergebnis === "melden";

/** Nimmt eine gesperrte Datei in die Meldung auf, wenn ihr Urteil "melden" lautet. */
function merkeGeschuetzt(rel, ergebnis) {
  if (ergebnis === "melden" && !schranke.geschuetzt.includes(rel)) schranke.geschuetzt.push(rel);
}

/** Prueft eine Datei an der Schranke; true, wenn sie den neuen Inhalt bekommen darf. */
function durchDieSchranke(rel, jetzt, neu) {
  const ergebnis = urteil(rel, jetzt, neu);
  merkeGeschuetzt(rel, ergebnis);
  if (gesperrt(ergebnis)) return false;
  if (ergebnis === "sichern") sichere(rel, jetzt);
  return true;
}

/**
 * Schreibt `inhalt` nach `pfad`, wenn die Schranke es zulaesst, und liefert, ob die Datei danach
 * den neuen Inhalt traegt. `davor` laeuft unmittelbar vor einem echten Schreiben (die Sicherung
 * der lokalen Config).
 */
function schreibeKitDatei(pfad, inhalt, { davor } = {}) {
  const rel = projektPfad(pfad);
  const neu = Buffer.from(inhalt, "utf-8");
  const jetzt = existsSync(pfad) ? readFileSync(pfad) : null;
  if (rel !== null && !durchDieSchranke(rel, jetzt, neu)) return false;
  if (jetzt === null || !jetzt.equals(neu)) {
    davor?.();
    mkdirSync(dirname(pfad), { recursive: true });
    writeFileSync(pfad, neu);
  }
  if (rel !== null) vermerke(rel, neu);
  return true;
}

/** Die Dateien unter `pfad`: er selbst, wenn er eine Datei ist, sonst alle darunter. */
function dateienUnter(pfad) {
  if (!statSync(pfad).isDirectory()) return [pfad];
  return readdirSync(pfad, { recursive: true }).map((d) => join(pfad, String(d))).filter((d) => statSync(d).isFile());
}

/**
 * Loescht die Datei oder den Ordner `pfad`, wenn die Schranke es fuer jede Datei darin zulaesst;
 * sonst bleibt alles stehen. Liefert, ob `pfad` danach fehlt.
 */
function entferneKitDatei(pfad) {
  if (!existsSync(pfad)) return true;
  // Erst alle Urteile, dann die Wirkung: Bleibt eine Datei stehen, wird keine gesichert.
  const dateien = dateienUnter(pfad).map((d) => ({ rel: projektPfad(d), jetzt: readFileSync(d) }))
    .map((d) => ({ ...d, ergebnis: d.rel === null ? "schreiben" : urteil(d.rel, d.jetzt, null) }));
  for (const { rel, ergebnis } of dateien) merkeGeschuetzt(rel, ergebnis);
  if (dateien.some(({ ergebnis }) => gesperrt(ergebnis))) return false;
  for (const { rel, jetzt, ergebnis } of dateien) if (ergebnis === "sichern") sichere(rel, jetzt);
  rmSync(pfad, { recursive: true, force: true });
  for (const { rel } of dateien) if (rel !== null) vermerke(rel, null);
  return true;
}

/** Schreibt den Datei-Stand, wenn der Lauf eine Datei des Projekts geschrieben oder geloescht hat. */
function schreibeDateiStand() {
  if (!schranke.beruehrt) return;
  const stand = dateiStand();
  const dateien = Object.fromEntries(Object.keys(stand).sort(vergleicheText).map((rel) => [rel, stand[rel]]));
  mkdirSync(dirname(resolve(DATEI_STAND)), { recursive: true });
  writeFileSync(resolve(DATEI_STAND), JSON.stringify({ dateien }, null, 2) + "\n", "utf-8");
}

/** Die Zeilen der Meldung zu geschuetzten Dateien und zur Sicherung; leer, wenn es keine gibt. */
function schrankeZeilen() {
  const zeilen = [];
  if (schranke.geschuetzt.length > 0) zeilen.push(t("geschuetztKopf"), ...geschuetzteDateien().map((rel) => `  ${rel}`));
  if (schranke.sicherung) zeilen.push(t("sicherungUpdate", { pfad: schranke.sicherung.split(sep).join("/") }));
  return zeilen;
}

const geschuetzteDateien = () => schranke.geschuetzt.toSorted(vergleicheText);

// --- Uncommittete Dateien im Workspace (Issue #1749) ---
//
// Der Runner haelt bei uncommitteten Dateien an. Der Installer zeigt darum jede Zeile von
// `git status --porcelain`, ohne die Ausnahmen des Runners: Einmal zu oft gewarnt ist billiger
// als ein abgebrochener Lauf.

/** Die Zeilen von `git status --porcelain`, oder `null` ohne git-Repo oder ohne git. */
function workspaceStand() {
  // Nicht ueber gitAntwort: Es kuerzt den Leerraum, und die erste Zeile verloere ihre Spalte.
  const res = cliSpawn("git", ["status", "--porcelain"], "INSTALL_GIT_FAKE", { encoding: "utf-8" });
  if (res.error || res.status !== 0) return null;
  return (res.stdout || "").split("\n").filter((zeile) => zeile.trim() !== "");
}

/**
 * Der Block aus dem Stand vor dem ersten Schreiben und dem am Ende, oder `null`, wenn nichts
 * liegt oder ein Stand fehlt. Eine Datei, die schon vorher in der Liste stand, gilt als
 * vorgefunden, auch wenn der Installer sie weiter geaendert hat.
 */
export function workspaceBlock(vorher, nachher, farbe = false) {
  if (!vorher || !nachher || nachher.length === 0) return null;
  const pfad = (zeile) => zeile.slice(3);
  const vorgefunden = new Set(vorher.map(pfad));
  const vomInstaller = nachher.filter((zeile) => !vorgefunden.has(pfad(zeile)));
  const lagVorher = nachher.filter((zeile) => vorgefunden.has(pfad(zeile)));
  const linie = "=".repeat(72);
  const kopf = farbe ? `\x1b[1;31m${t("workspaceKopf")}\x1b[0m` : t("workspaceKopf");
  const zeilen = ["", "", linie, kopf, linie];
  if (vomInstaller.length > 0) zeilen.push(t("workspaceInstaller"), ...vomInstaller.map((z) => `  ${z}`));
  if (lagVorher.length > 0) zeilen.push(t("workspaceVorher"), ...lagVorher.map((z) => `  ${z}`));
  zeilen.push("", t("workspaceRunner"), linie, "");
  return zeilen.join("\n");
}

function meldeWorkspace(vorher) {
  const block = workspaceBlock(vorher, vorher && workspaceStand(), Boolean(process.stdout.isTTY));
  if (block) console.log(block);
}

// Nur als CLI ausfuehren, nicht beim Import (z. B. durch die node:test-Suite, #135).
// realpathSync statt resolve: Node loest fuer import.meta.url Symlinks auf (macOS:
// /var -> /private/var), ein nur normalisierter argv[1] wuerde dann nie matchen (#146).
let runAsCli = false;
if (process.argv[1]) {
  try {
    runAsCli = realpathSync(process.argv[1]) === fileURLToPath(import.meta.url);
  } catch { /* argv[1] nicht aufloesbar -> kein CLI-Start */ }
}
if (runAsCli) {
  try {
    await main();
    schreibeDateiStand();
  } catch (err) {
    console.error(t("fehlerKopf"), err.message);
    schreibeDateiStand();
    process.exit(1);
  }
}
